def _is_pat_token(token):
    return str(token or "").strip().startswith("pat_")


def _token_uses_deriv_otp_ws(token, token_type=None):
    token_type = str(token_type or "").strip().lower()
    return token_type == "oauth"


def _mask_api_token(token):
    token = str(token or "").strip()
    if not token:
        return ""
    if len(token) <= 10:
        return f"{token[:4]}..."
    return f"{token[:8]}...{token[-3:]}"


def _extract_deriv_rest_error(body_text):
    body_text = str(body_text or "").strip()
    if not body_text:
        return "Deriv OTP request failed"
    try:
        payload = json.loads(body_text)
        error = payload.get("error")
        if isinstance(error, dict):
            return str(error.get("message") or error.get("code") or body_text[:300])
        if isinstance(error, str):
            return error
        return str(payload.get("message") or body_text[:300])
    except Exception:
        return body_text[:300]


def _sanitize_deriv_oauth_response_text(body_text):
    try:
        payload = json.loads(str(body_text or "") or "{}")
        if isinstance(payload, dict):
            for key in ("access_token", "refresh_token", "id_token"):
                if key in payload:
                    payload[key] = "<redacted>"
            return json.dumps(payload, separators=(",", ":"))[:1000]
    except Exception:
        pass
    return str(body_text or "")[:1000]


def _safe_deriv_payload_text(payload):
    try:
        return json.dumps(payload, separators=(",", ":"), sort_keys=True)
    except Exception:
        return str(payload)


def _deriv_connection_type(state):
    return str((state or {}).get("api_token_type") or "legacy").strip().lower() or "legacy"


def _deriv_trade_connection_mode(state):
    token_type = _deriv_connection_type(state)
    if token_type == "oauth":
        return "oauth"
    return "legacy_token"


def _uses_new_deriv_trade_api(state):
    return _deriv_trade_connection_mode(state) == "oauth"


def _proposal_payload_for_connection(state, payload):
    final_payload = dict(payload or {})
    if _uses_new_deriv_trade_api(state) and "symbol" in final_payload:
        symbol = str(final_payload.pop("symbol") or "").strip()
        if symbol:
            final_payload["underlying_symbol"] = symbol
    if _uses_new_deriv_trade_api(state):
        contract_type = _normalize_deriv_contract_type(final_payload.get("contract_type"))
        for unsupported_key in (
            "loginid",
            "product_type",
            "barrier_range",
            "landing_company_short",
            "date_start",
            "trade_risk_profile",
            "trading_period_start",
        ):
            final_payload.pop(unsupported_key, None)
        if contract_type in {
            "CALL",
            "PUT",
            "DIGITOVER",
            "DIGITUNDER",
            "DIGITMATCH",
            "DIGITDIFF",
            "DIGITEVEN",
            "DIGITODD",
            "ONETOUCH",
            "NOTOUCH",
        }:
            final_payload.pop("barrier2", None)
        if contract_type in ("DIGITEVEN", "DIGITODD"):
            final_payload.pop("barrier", None)
            final_payload.pop("barrier2", None)
    return final_payload


def _proposal_error_text(error):
    if isinstance(error, dict):
        pieces = [
            error.get("message"),
            error.get("code"),
            error.get("error"),
            error.get("details"),
            error.get("validation"),
        ]
        return " ".join(str(piece) for piece in pieces if piece not in (None, ""))
    return str(error or "")


def _is_proposal_rate_limit_error(error):
    text = _proposal_error_text(error).lower()
    return bool(
        text
        and (
            ("proposal" in text and "limit" in text)
            or ("rate" in text and "limit" in text)
            or "too many" in text
            or "ratelimit" in text
        )
    )


def _friendly_proposal_error_message(error):
    if _is_proposal_rate_limit_error(error):
        return "Deriv quote limit reached. Waiting a moment before trying again."
    text = _proposal_error_text(error).strip()
    return text or "Quote error"


def _is_noisy_deriv_rate_limit_message(value):
    text = str(value or "").lower()
    if not text:
        return False
    return bool(
        ("proposal" in text and "limit" in text)
        or ("rate" in text and "limit" in text)
        or "too many" in text
        or "ratelimit" in text
        or "exceeded" in text and ("buy" in text or "proposal" in text or "rate" in text)
        or "contract proposal" in text and ("reached" in text or "limit" in text)
    )


def _should_suppress_user_rate_limit_popup(state, message):
    return bool(
        _deriv_trade_connection_mode(state) == "legacy_token"
        and _is_noisy_deriv_rate_limit_message(message)
    )


def _is_deriv_trade_validation_error_text(value):
    text = str(value or "").lower()
    return any(
        token in text
        for token in (
            "contractbuyvalidationerror",
            "invalidbarrier",
            "invalid barrier",
            "invalidsymbol",
            "invalid symbol",
            "unknown contract_type",
            "contract type",
            "properties not allowed",
        )
    )


def _mark_proposal_rate_limited(state, error):
    if not isinstance(state, dict) or not _is_proposal_rate_limit_error(error):
        return False
    try:
        state["proposal_rate_limited_until"] = max(
            float(state.get("proposal_rate_limited_until", 0.0) or 0.0),
            time.time() + max(0.2, float(DERIV_PROPOSAL_RATE_LIMIT_COOLDOWN_SEC)),
        )
    except Exception:
        state["proposal_rate_limited_until"] = time.time() + 2.5
    return True


def _proposal_rate_limit_wait_message(state):
    if not isinstance(state, dict):
        return None
    try:
        remaining = float(state.get("proposal_rate_limited_until", 0.0) or 0.0) - time.time()
    except Exception:
        remaining = 0.0
    if remaining <= 0:
        return None
    return f"Deriv quote limit reached. Waiting {max(1, int(math.ceil(remaining)))}s before trying again."


def _resolve_request_waiter(state, waiter_key, req_id, payload=None, error=None):
    if req_id in (None, ""):
        return False
    waiters = (state or {}).get(waiter_key)
    if not isinstance(waiters, dict):
        return False
    candidate_keys = [req_id, str(req_id)]
    try:
        normalized_int = int(float(req_id))
        candidate_keys.append(normalized_int)
        candidate_keys.append(str(normalized_int))
    except Exception:
        pass
    waiter = None
    used_key = None
    for key in candidate_keys:
        waiter = waiters.get(key)
        if waiter is not None:
            used_key = key
            break
    if waiter is not None and used_key is not None:
        waiters.pop(used_key, None)
    if waiter is None:
        return False
    if error:
        try:
            logger.warning(
                "deriv_request_waiter_error waiter=%s req_id=%s failed_at=%s error=%s",
                waiter_key,
                req_id,
                "contracts_for_error" if waiter_key == "_contracts_for_waiters" else waiter_key,
                _safe_deriv_payload_text(error),
            )
        except Exception:
            pass
    waiter["payload"] = payload
    waiter["error"] = error
    try:
        evt = waiter.get("event")
        if evt:
            evt.set()
    except Exception:
        pass
    return True


def _send_ws_request_for_response(client_id, state, payload, response_key, waiter_key, timeout_sec=5.0):
    ws = state.get("ws") if isinstance(state, dict) else None
    if not ws:
        return None, "Not connected"
    req_id = payload.get("req_id") or _new_req_id()
    payload = dict(payload or {})
    payload["req_id"] = req_id
    waiter = {"event": threading.Event(), "payload": None, "error": None}
    waiters = state.setdefault(waiter_key, {})
    waiters[req_id] = waiter
    waiters[str(req_id)] = waiter
    try:
        ws.send(json.dumps(payload))
    except Exception as exc:
        waiters.pop(req_id, None)
        waiters.pop(str(req_id), None)
        if client_id and _should_force_ws_reconnect_on_send_exception(state, exc):
            _mark_ws_unhealthy_and_reconnect(client_id, state, "Deriv connection failed while validating market data. Reconnecting now...", emit_error=False)
        elif client_id:
            logger.warning(
                "[%s] trade_failed_without_disconnect=true failed_at=%s_send error=%s ws_ready_state=%s",
                client_id,
                response_key,
                exc,
                _websocket_ready_state_label(state),
            )
        return None, str(exc)
    if not waiter["event"].wait(max(0.40, float(timeout_sec))):
        waiters.pop(req_id, None)
        waiters.pop(str(req_id), None)
        return None, f"{response_key} timeout"
    waiters.pop(req_id, None)
    waiters.pop(str(req_id), None)
    if waiter.get("error"):
        return None, _proposal_error_text(waiter.get("error")) or f"{response_key} error"
    return waiter.get("payload"), None


_ACTIVE_SYMBOLS_CACHE_TTL_SEC = 300.0
_CONTRACTS_FOR_CACHE_TTL_SEC = 300.0
_LEGACY_SYMBOL_ALIASES = {
    "R_10": ("R_10",),
    "R_25": ("R_25",),
    "R_50": ("R_50",),
    "R_75": ("R_75",),
    "R_100": ("R_100",),
}


def _client_id_for_state(state):
    for _cid, _state in clients.items():
        if _state is state:
            return _cid
    return None


def _get_active_symbols_for_state(client_id, state, force_refresh=False):
    now_ts = time.time()
    cached = state.get("active_symbols_cache") if isinstance(state, dict) else None
    if (
        not force_refresh
        and isinstance(cached, dict)
        and isinstance(cached.get("symbols"), list)
        and (now_ts - float(cached.get("ts", 0.0) or 0.0)) < _ACTIVE_SYMBOLS_CACHE_TTL_SEC
    ):
        return cached.get("symbols") or [], None
    payload, err = _send_ws_request_for_response(
        client_id,
        state,
        {"active_symbols": "brief", "req_id": _new_req_id()},
        "active_symbols",
        "_active_symbols_waiters",
        timeout_sec=6.0,
    )
    if err:
        return [], err
    symbols = payload.get("active_symbols") if isinstance(payload, dict) else None
    if not isinstance(symbols, list):
        return [], "active_symbols returned no markets"
    state["active_symbols_cache"] = {"ts": now_ts, "symbols": symbols}
    return symbols, None


def _resolve_deriv_underlying_symbol(client_id, state, requested_symbol):
    original = str(requested_symbol or "").strip()
    if not original:
        return None, "Invalid symbol for new Deriv API: "
    if not _uses_new_deriv_trade_api(state):
        return original, None
    symbols, err = _get_active_symbols_for_state(client_id, state)
    if err:
        return None, err
    by_symbol = {}
    for item in symbols:
        if not isinstance(item, dict):
            continue
        symbol = str(item.get("symbol") or item.get("underlying_symbol") or "").strip()
        if symbol:
            by_symbol[symbol.upper()] = symbol
    requested_upper = original.upper()
    if requested_upper in by_symbol:
        return by_symbol[requested_upper], None
    for alias in _LEGACY_SYMBOL_ALIASES.get(requested_upper, ()):
        if str(alias).upper() in by_symbol:
            return by_symbol[str(alias).upper()], None
    return None, f"Invalid symbol for new Deriv API: {original}"


def resolve_new_api_symbol(state, requested_symbol, context="", client_id=None):
    original = str(requested_symbol or "").strip()
    if not _uses_new_deriv_trade_api(state):
        return original, None
    cid = client_id or _client_id_for_state(state)
    resolved, err = _resolve_deriv_underlying_symbol(cid, state, original)
    if err:
        logger.info(
            "[%s] skipped_invalid_symbol=%s context=%s mode=%s error=%s",
            cid or "?",
            original,
            context or "",
            _deriv_trade_connection_mode(state),
            err,
        )
        return None, err
    if resolved and resolved != original:
        logger.info(
            "[%s] new_api_symbol_resolved original=%s resolved=%s context=%s mode=%s",
            cid or "?",
            original,
            resolved,
            context or "",
            _deriv_trade_connection_mode(state),
        )
    return resolved, None


def _filter_new_api_symbols(state, symbols, context="", client_id=None, max_symbols=None):
    items = []
    seen = set()
    for symbol in list(symbols or []):
        resolved, _err = resolve_new_api_symbol(state, symbol, context=context, client_id=client_id)
        if not resolved:
            continue
        key = str(resolved).upper()
        if key in seen:
            continue
        seen.add(key)
        items.append(resolved)
        if max_symbols and len(items) >= int(max_symbols):
            break
    return items


def _first_valid_new_api_symbol(state, symbols, context="", client_id=None):
    filtered = _filter_new_api_symbols(state, symbols, context=context, client_id=client_id, max_symbols=1)
    return filtered[0] if filtered else None



def _get_contracts_for_symbol(client_id, state, underlying_symbol, force_refresh=False):
    symbol = str(underlying_symbol or "").strip()
    if not symbol:
        return None, "Invalid symbol"
    cache = state.setdefault("contracts_for_cache", {})
    now_ts = time.time()
    cached = cache.get(symbol.upper())
    if (
        not force_refresh
        and isinstance(cached, dict)
        and (now_ts - float(cached.get("ts", 0.0) or 0.0)) < _CONTRACTS_FOR_CACHE_TTL_SEC
    ):
        return cached.get("contracts_for"), None
    payload = {"contracts_for": symbol, "req_id": _new_req_id()}
    if not _uses_new_deriv_trade_api(state):
        payload["currency"] = "USD"
    logger.info(
        "[%s] deriv_contracts_for_send mode=%s payload=%s",
        client_id,
        _deriv_trade_connection_mode(state),
        _safe_deriv_payload_text(payload),
    )
    payload, err = _send_ws_request_for_response(
        client_id,
        state,
        payload,
        "contracts_for",
        "_contracts_for_waiters",
        timeout_sec=6.0,
    )
    if err:
        logger.warning(
            "[%s] deriv_contracts_for_error mode=%s failed_at=contracts_for_error symbol=%s error=%s response=%s",
            client_id,
            _deriv_trade_connection_mode(state),
            symbol,
            err,
            _safe_deriv_payload_text(payload or {}),
        )
        return None, err
    logger.info(
        "[%s] deriv_contracts_for_response mode=%s symbol=%s response=%s",
        client_id,
        _deriv_trade_connection_mode(state),
        symbol,
        _safe_deriv_payload_text(payload or {}),
    )
    contracts_for = payload.get("contracts_for") if isinstance(payload, dict) else None
    if not isinstance(contracts_for, dict):
        return None, "contracts_for returned no contract list"
    cache[symbol.upper()] = {"ts": now_ts, "contracts_for": contracts_for}
    return contracts_for, None


def _contracts_for_has_contract_type(contracts_for, contract_type):
    wanted = str(contract_type or "").upper().strip()
    if not wanted:
        return False
    return bool(_contracts_for_candidates(contracts_for, wanted))


_DERIV_CONTRACT_ALIASES = {
    "OVER": "DIGITOVER",
    "UNDER": "DIGITUNDER",
    "MATCHES": "DIGITMATCH",
    "MATCH": "DIGITMATCH",
    "DIFFERS": "DIGITDIFF",
    "DIFFER": "DIGITDIFF",
    "DIFF": "DIGITDIFF",
    "DIGITDIFFERS": "DIGITDIFF",
    "DIGITMATCHES": "DIGITMATCH",
    "EVEN": "DIGITEVEN",
    "ODD": "DIGITODD",
    "HIGHER": "CALL",
    "LOWER": "PUT",
    "RISE": "CALL",
    "FALL": "PUT",
    "TOUCH": "ONETOUCH",
    "NO_TOUCH": "NOTOUCH",
    "NO TOUCH": "NOTOUCH",
    "NO-TOUCH": "NOTOUCH",
    "NOTOUCH": "NOTOUCH",
}


_DERIV_DIGIT_CONTRACT_TYPES = {
    "DIGITOVER",
    "DIGITUNDER",
    "DIGITMATCH",
    "DIGITDIFF",
    "DIGITEVEN",
    "DIGITODD",
}


def _normalize_deriv_contract_type(value):
    raw = str(value or "").upper().strip()
    if not raw:
        return ""
    match = re.match(r"^(OVER|UNDER|MATCHES|MATCH|DIFFERS|DIFFER|DIFF)\s+([0-9])$", raw)
    if match:
        return _DERIV_CONTRACT_ALIASES.get(match.group(1), raw)
    return _DERIV_CONTRACT_ALIASES.get(raw, raw)


def _barrier_from_trade_label(contract_type, barrier):
    if barrier not in (None, ""):
        return barrier
    match = re.search(r"\b([0-9])\b", str(contract_type or ""))
    if match:
        return int(match.group(1))
    return barrier


def _contracts_for_candidates(contracts_for, contract_type):
    wanted = str(contract_type or "").upper().strip()
    return [
        item for item in ((contracts_for or {}).get("available") or [])
        if str((item or {}).get("contract_type") or "").upper().strip() == wanted
    ]


def _contract_item_barrier_values(item):
    values = []
    for key in ("barrier", "barrier1"):
        value = (item or {}).get(key)
        if value not in (None, ""):
            values.append(str(value).strip())
    for key in ("barrier_choices", "barrier_range"):
        value = (item or {}).get(key)
        if isinstance(value, (list, tuple)):
            values.extend(str(v).strip() for v in value if v not in (None, ""))
    return [v for v in values if v]


def _contract_item_duration_matches(item, duration, duration_unit):
    try:
        return _duration_matches_contracts_for(item, int(float(duration or 0)), str(duration_unit or "t").lower())
    except Exception:
        return True


def _contract_item_supports_second_barrier(item):
    if not isinstance(item, dict):
        return False
    try:
        barriers_count = int(float(item.get("barriers") or 0))
    except Exception:
        barriers_count = 0
    return bool(barriers_count >= 2 and item.get("barrier2") not in (None, ""))


def _contract_item_allows_no_barrier(item):
    try:
        barriers_count = int(float((item or {}).get("barriers") or 0))
    except Exception:
        barriers_count = 0
    barrier_category = str((item or {}).get("barrier_category") or "").strip().lower()
    return barriers_count <= 0 and not _contract_item_barrier_values(item) and barrier_category in ("", "none", "no_barrier")


def resolve_new_api_barrier(state, contracts_for, contract_type, requested_barrier, duration, duration_unit, context="", client_id=None):
    deriv_contract = _normalize_deriv_contract_type(contract_type)
    if not _uses_new_deriv_trade_api(state):
        return requested_barrier, None
    cid = client_id or _client_id_for_state(state)
    raw = requested_barrier
    if deriv_contract in ("DIGITOVER", "DIGITUNDER", "DIGITMATCH", "DIGITDIFF"):
        try:
            digit = int(float(raw))
        except Exception:
            return None, f"Invalid barrier for {deriv_contract}: {raw}"
        if digit < 0 or digit > 9:
            return None, f"Invalid barrier for {deriv_contract}: {raw}"
        return digit, None
    if deriv_contract in ("DIGITEVEN", "DIGITODD"):
        return None, None

    candidates = _contracts_for_candidates(contracts_for, deriv_contract)
    if not candidates:
        return raw, None
    raw_text = "" if raw in (None, "") else str(raw).strip()
    if deriv_contract in ("CALL", "PUT"):
        if not raw_text:
            return None, None
        for item in candidates:
            if _contract_item_allows_no_barrier(item):
                logger.info(
                    "[%s] new_api_barrier_removed context=%s contract_type=%s requested_barrier=%s reason=contracts_for_allows_no_barrier",
                    cid or "?",
                    context or "",
                    deriv_contract,
                    raw_text,
                )
                return None, None
        for item in candidates:
            values = _contract_item_barrier_values(item)
            if raw_text in values:
                return raw_text, None
        for item in candidates:
            values = _contract_item_barrier_values(item)
            if values:
                logger.info(
                    "[%s] new_api_barrier_replaced context=%s contract_type=%s requested_barrier=%s resolved_barrier=%s",
                    cid or "?",
                    context or "",
                    deriv_contract,
                    raw_text,
                    values[0],
                )
                return values[0], None
        return None, f"No valid barrier is available for {deriv_contract}"

    if deriv_contract in ("ONETOUCH", "NOTOUCH"):
        for item in candidates:
            values = _contract_item_barrier_values(item)
            if raw_text and raw_text in values:
                return raw_text, None
        for item in candidates:
            values = _contract_item_barrier_values(item)
            if values:
                resolved = raw_text if raw_text in values else values[0]
                if raw_text and raw_text != resolved:
                    logger.info(
                        "[%s] new_api_barrier_replaced context=%s contract_type=%s requested_barrier=%s resolved_barrier=%s",
                        cid or "?",
                        context or "",
                        deriv_contract,
                        raw_text,
                        resolved,
                    )
                return resolved, None
        return None, f"No valid barrier is available for {deriv_contract}"

    return raw, None


_NEW_API_SINGLE_BARRIER_CONTRACTS = {
    "CALL",
    "PUT",
    "DIGITOVER",
    "DIGITUNDER",
    "DIGITMATCH",
    "DIGITDIFF",
    "DIGITEVEN",
    "DIGITODD",
    "ONETOUCH",
    "NOTOUCH",
}


def sanitize_new_api_trade_payload(state, payload, *, contracts_for=None, contract_type=None, context="", client_id=None):
    original = dict(payload or {})
    sanitized = dict(payload or {})
    removed = {}
    if not _uses_new_deriv_trade_api(state):
        return sanitized, removed
    deriv_contract = _normalize_deriv_contract_type(contract_type or sanitized.get("contract_type"))
    if deriv_contract in _NEW_API_SINGLE_BARRIER_CONTRACTS and "barrier2" in sanitized:
        removed["barrier2"] = sanitized.pop("barrier2", None)
    if deriv_contract in ("DIGITEVEN", "DIGITODD"):
        if "barrier" in sanitized:
            removed["barrier"] = sanitized.pop("barrier", None)
        if "barrier2" in sanitized:
            removed["barrier2"] = sanitized.pop("barrier2", None)
    if deriv_contract in ("DIGITOVER", "DIGITUNDER", "DIGITMATCH", "DIGITDIFF") and sanitized.get("barrier") not in (None, ""):
        try:
            sanitized["barrier"] = int(float(sanitized.get("barrier")))
        except Exception:
            pass
    if removed:
        logger.info(
            "[%s] new_api_payload_sanitized context=%s contract_type=%s removed_fields=%s original_payload=%s sanitized_payload=%s",
            client_id or _client_id_for_state(state) or "?",
            context or "",
            deriv_contract,
            ",".join(sorted(removed.keys())),
            _safe_deriv_payload_text(original),
            _safe_deriv_payload_text(sanitized),
        )
    return sanitized, removed


def sanitize_new_api_trade_parameters(
    state,
    client_id,
    contracts_for,
    deriv_contract,
    parameters,
    requested_barrier,
    duration,
    duration_unit,
    context,
):
    original = dict(parameters or {})
    sanitized = dict(parameters or {})
    removed = {}
    matched_item = None
    resolved_barrier = None
    if not _uses_new_deriv_trade_api(state):
        return sanitized, None, {"removed": removed, "matched_item": matched_item, "resolved_barrier": resolved_barrier}

    contract_type = _normalize_deriv_contract_type(deriv_contract)
    candidates = [
        item for item in _contracts_for_candidates(contracts_for, contract_type)
        if _contract_item_duration_matches(item, duration, duration_unit)
    ] or _contracts_for_candidates(contracts_for, contract_type)
    if candidates:
        matched_item = candidates[0]

    def remove_field(name):
        if name in sanitized:
            removed[name] = sanitized.pop(name, None)

    if contract_type in _NEW_API_SINGLE_BARRIER_CONTRACTS:
        remove_field("barrier2")

    if contract_type in ("DIGITOVER", "DIGITUNDER", "DIGITMATCH", "DIGITDIFF"):
        try:
            digit = int(float(requested_barrier))
        except Exception:
            return sanitized, f"Invalid barrier for {contract_type}: {requested_barrier}", {"removed": removed, "matched_item": matched_item, "resolved_barrier": resolved_barrier}
        if digit < 0 or digit > 9:
            return sanitized, f"Invalid barrier for {contract_type}: {requested_barrier}", {"removed": removed, "matched_item": matched_item, "resolved_barrier": resolved_barrier}
        sanitized["barrier"] = digit
        resolved_barrier = digit
    elif contract_type in ("DIGITEVEN", "DIGITODD"):
        remove_field("barrier")
        remove_field("barrier2")
        resolved_barrier = None
    elif contract_type in ("CALL", "PUT"):
        no_barrier_allowed = any(_contract_item_allows_no_barrier(item) for item in candidates)
        if no_barrier_allowed:
            remove_field("barrier")
            remove_field("barrier2")
            resolved_barrier = None
        else:
            valid_values = []
            for item in candidates:
                valid_values.extend(_contract_item_barrier_values(item))
            valid_values = [str(v).strip() for v in valid_values if str(v).strip()]
            requested_text = "" if requested_barrier in (None, "") else str(requested_barrier).strip()
            if requested_text and requested_text in valid_values:
                sanitized["barrier"] = requested_text
                resolved_barrier = requested_text
            elif valid_values:
                sanitized["barrier"] = valid_values[0]
                resolved_barrier = valid_values[0]
            else:
                remove_field("barrier")
                remove_field("barrier2")
                if candidates:
                    resolved_barrier = None
                else:
                    return sanitized, "Invalid barrier for CALL/PUT on this market/duration", {"removed": removed, "matched_item": matched_item, "resolved_barrier": resolved_barrier}
    elif contract_type in ("ONETOUCH", "NOTOUCH"):
        remove_field("barrier2")
        valid_values = []
        for item in candidates:
            valid_values.extend(_contract_item_barrier_values(item))
        valid_values = [str(v).strip() for v in valid_values if str(v).strip()]
        requested_text = "" if requested_barrier in (None, "") else str(requested_barrier).strip()
        if requested_text and requested_text in valid_values:
            sanitized["barrier"] = requested_text
            resolved_barrier = requested_text
        elif valid_values:
            sanitized["barrier"] = valid_values[0]
            resolved_barrier = valid_values[0]
        else:
            return sanitized, f"Invalid barrier for {contract_type} on this market/duration", {"removed": removed, "matched_item": matched_item, "resolved_barrier": resolved_barrier}
    else:
        sanitized, removed_extra = sanitize_new_api_trade_payload(
            state,
            sanitized,
            contracts_for=contracts_for,
            contract_type=contract_type,
            context=context,
            client_id=client_id,
        )
        removed.update(removed_extra)

    logger.info(
        "[%s] new_api_trade_parameters_sanitized context=%s contract_type=%s original_parameters=%s sanitized_parameters=%s removed_fields=%s resolved_barrier=%s matched_contract=%s",
        client_id or _client_id_for_state(state) or "?",
        context or "",
        contract_type,
        _safe_deriv_payload_text(original),
        _safe_deriv_payload_text(sanitized),
        ",".join(sorted(removed.keys())),
        resolved_barrier,
        _safe_deriv_payload_text(matched_item or {}),
    )
    return sanitized, None, {"removed": removed, "matched_item": matched_item, "resolved_barrier": resolved_barrier}


