def _websocket_ready_state_label(state):
    ws = (state or {}).get("ws") if isinstance(state, dict) else None
    if not ws:
        return "missing"
    try:
        sock = getattr(ws, "sock", None)
        if sock is not None and bool(getattr(sock, "connected", False)):
            return "open"
        if sock is not None:
            return "closed"
    except Exception:
        pass
    if bool((state or {}).get("ws_transport_connected")):
        return "transport_connected"
    return "unknown"


def _is_otp_authenticated_socket(state):
    if not isinstance(state, dict):
        return False
    return bool(
        _token_uses_deriv_otp_ws(state.get("api_token"), state.get("api_token_type"))
        and state.get("ws_connected")
        and state.get("ws")
    )


def _build_digit_proposal_payload(req_id, deriv_contract, stake, symbol, barrier, duration, duration_unit):
    return {
        "proposal": 1,
        "amount": float(stake),
        "basis": "stake",
        "contract_type": str(deriv_contract or "").upper().strip(),
        "currency": "USD",
        "duration": int(duration),
        "duration_unit": str(duration_unit or "t").lower(),
        "symbol": str(symbol or "").strip(),
        "barrier": str(int(barrier)),
        "req_id": req_id,
    }


def _request_digit_proposal_for_buy(client_id, state, payload, timeout_sec=5.0):
    ws = state.get("ws") if isinstance(state, dict) else None
    if not ws:
        return None, "Not connected"
    rate_limit_msg = _proposal_rate_limit_wait_message(state)
    if rate_limit_msg:
        return None, rate_limit_msg
    payload = _proposal_payload_for_connection(state, payload)
    req_id = payload.get("req_id")
    waiter = {"event": threading.Event(), "proposal": None, "error": None}
    waiters = state.setdefault("_proposal_waiters", {})
    waiters[req_id] = waiter
    waiters[str(req_id)] = waiter
    logger.info(
        "[%s] TEMP proposal_about_to_be_sent token_type=%s payload=%s",
        client_id,
        _deriv_connection_type(state),
        _safe_deriv_payload_text(payload),
    )
    try:
        ws.send(json.dumps(payload))
        logger.info("[%s] TEMP proposal_actually_sent req_id=%s token_type=%s", client_id, req_id, _deriv_connection_type(state))
    except Exception as exc:
        waiters.pop(req_id, None)
        waiters.pop(str(req_id), None)
        return None, str(exc)
    if not waiter["event"].wait(max(0.40, float(timeout_sec))):
        waiters.pop(req_id, None)
        waiters.pop(str(req_id), None)
        return None, "Proposal timeout"
    waiters.pop(req_id, None)
    waiters.pop(str(req_id), None)
    if waiter.get("error"):
        err_payload = waiter.get("error")
        _mark_proposal_rate_limited(state, err_payload)
        return None, _friendly_proposal_error_message(err_payload)
    proposal = waiter.get("proposal") or {}
    proposal_id = proposal.get("id")
    if proposal_id in (None, ""):
        return None, "Proposal id missing"
    return proposal, None


def _send_buy_from_proposal(client_id, state, req_id, proposal, stake):
    ws = state.get("ws") if isinstance(state, dict) else None
    proposal_id = (proposal or {}).get("id")
    if not ws:
        return False, "Not connected"
    if proposal_id in (None, ""):
        return False, "Proposal id missing"
    ask_price = _safe_float((proposal or {}).get("ask_price"), _safe_float((proposal or {}).get("display_value"), stake))
    buy_payload = {
        "req_id": req_id,
        "buy": proposal_id,
        "price": float(ask_price if ask_price is not None else stake),
    }
    logger.info(
        "[%s] TEMP buy_about_to_be_sent token_type=%s payload=%s",
        client_id,
        _deriv_connection_type(state),
        _safe_deriv_payload_text(buy_payload),
    )
    ws.send(json.dumps(buy_payload))
    logger.info("[%s] TEMP buy_actually_sent req_id=%s token_type=%s", client_id, req_id, _deriv_connection_type(state))
    return True, "Trade sent"


def _proposal_profit_value(proposal, stake):
    proposal = proposal or {}
    ask_price = _safe_float(proposal.get("ask_price"), _safe_float(proposal.get("display_value"), stake))
    payout = _safe_float(proposal.get("payout"), None)
    profit = _safe_float(proposal.get("profit"), None)
    if profit is None and ask_price is not None and payout is not None:
        profit = float(payout) - float(ask_price)
    return profit


def _request_min_profit_proposal_for_buy(client_id, state, base_payload, req_meta, *, stake, minimum_profit, retries=0, buy_best_available=False):
    try:
        min_profit = float(minimum_profit)
    except Exception:
        min_profit = 0.0
    max_attempts = max(1, min(8, 1 + int(retries or 0)))
    original_req_id = base_payload.get("req_id")
    best_profit = None
    best_response = None
    best_req_id = None
    last_error = None
    for attempt in range(max_attempts):
        req_id = original_req_id if attempt == 0 else _new_req_id()
        payload = dict(base_payload or {})
        payload["req_id"] = req_id
        if req_id != original_req_id:
            state.setdefault("req_meta", {})[req_id] = dict(req_meta or {})
        proposal, err = _request_digit_proposal_for_buy(client_id, state, payload, timeout_sec=5.0)
        if err:
            last_error = err
            if req_id != original_req_id:
                try:
                    state.get("req_meta", {}).pop(req_id, None)
                except Exception:
                    pass
            break
        profit = _proposal_profit_value(proposal, stake)
        logger.info(
            "[%s] matches_frenzy_profit_gate attempt=%s/%s proposal_profit=%s minimum_profit=%s proposal=%s",
            client_id,
            attempt + 1,
            max_attempts,
            None if profit is None else round(float(profit), 4),
            round(float(min_profit), 4),
            _safe_deriv_payload_text(proposal or {}),
        )
        if profit is not None and float(profit) + 1e-9 >= min_profit:
            if best_req_id not in (None, req_id):
                try:
                    state.get("req_meta", {}).pop(best_req_id, None)
                    state.get("req_meta", {}).pop(str(best_req_id), None)
                except Exception:
                    pass
            if req_id != original_req_id:
                try:
                    state.get("req_meta", {}).pop(original_req_id, None)
                    state.get("req_meta", {}).pop(str(original_req_id), None)
                except Exception:
                    pass
            return req_id, proposal, None
        if profit is not None and (best_profit is None or float(profit) > float(best_profit)):
            if best_req_id not in (None, req_id):
                try:
                    state.get("req_meta", {}).pop(best_req_id, None)
                    state.get("req_meta", {}).pop(str(best_req_id), None)
                except Exception:
                    pass
            best_profit = profit
            best_response = proposal
            best_req_id = req_id
        elif req_id != original_req_id:
            try:
                state.get("req_meta", {}).pop(req_id, None)
            except Exception:
                pass
        if req_id != original_req_id:
            pass
    if buy_best_available and best_response:
        logger.info(
            "[%s] matches_frenzy_profit_gate_best_available selected_profit=%s target_profit=%s proposal=%s",
            client_id,
            None if best_profit is None else round(float(best_profit), 4),
            round(float(min_profit), 4),
            _safe_deriv_payload_text(best_response or {}),
        )
        return best_req_id or original_req_id, best_response, None
    msg = f"Matches Frenzy skipped: proposal profit {float(best_profit or 0.0):.2f} below target {float(min_profit):.2f}"
    if last_error and best_response is None:
        msg = last_error
    return None, best_response, msg


def _execute_oauth_options_trade_engine(trade_request, *, state, req_id, stake, duration, duration_unit):
    from deriv_engines.oauth_engine import OAuthDerivTradeEngine
    from deriv_engines.trade_intent import TradeIntent

    deps = {
        "logger": logger,
        "connection_mode": _deriv_trade_connection_mode,
        "is_demo": _oauth_account_is_demo,
        "mask_account": _mask_account_id,
        "ws_ready_state": _websocket_ready_state_label,
        "otp_authenticated": _is_otp_authenticated_socket,
        "active_symbols": _get_active_symbols_for_state,
        "contracts_for": _get_contracts_for_symbol,
        "legacy_aliases": _LEGACY_SYMBOL_ALIASES,
        "duration_matches": _duration_matches_contracts_for,
        "safe_payload": _safe_deriv_payload_text,
        "proposal_payload_for_connection": _proposal_payload_for_connection,
        "request_proposal": _request_digit_proposal_for_buy,
        "new_req_id": _new_req_id,
        "debug_log": _deriv_trade_debug_log,
        "safe_float": _safe_float,
        "now_time": now_time,
        "stamp_latency": _stamp_trade_latency,
        "mark_ws_unhealthy": _mark_ws_unhealthy_and_reconnect,
        "should_force_reconnect": _should_force_ws_reconnect_on_send_exception,
    }
    intent = TradeIntent.from_request(
        trade_request,
        state=state,
        req_id=req_id,
        stake=stake,
        duration=duration,
        duration_unit=duration_unit,
    )
    return OAuthDerivTradeEngine(deps).execute(intent, state=state)


def execute_deriv_trade(trade_request):
    trade_request = trade_request or {}
    client_id = trade_request.get("client_id")
    state = trade_request.get("state") or clients.get(client_id)
    if not client_id or not isinstance(state, dict):
        return False, "No client state"
    ready, ready_msg = _ensure_trade_socket_ready(client_id, state)
    if not ready:
        return False, ready_msg
    ws = state.get("ws")
    if not ws:
        return False, "Not connected"

    req_id = trade_request.get("req_id") or _new_req_id()
    requested_symbol = str(trade_request.get("symbol") or state.get("current_symbol") or "R_10").strip()
    requested_contract = str(trade_request.get("contract_type") or "").strip()
    deriv_contract = _normalize_deriv_contract_type(requested_contract)
    if not deriv_contract:
        return False, "Invalid contract type"

    try:
        stake = float(trade_request.get("stake"))
    except Exception:
        stake = 0.0
    if stake <= 0:
        return False, "Invalid stake"

    duration_unit = _normalize_trade_duration_unit(trade_request.get("duration_unit", "t"))
    duration = _sanitize_trade_duration_for_unit(trade_request.get("duration", 1), duration_unit, default=1)
    if _uses_new_deriv_trade_api(state):
        return _execute_oauth_options_trade_engine(
            trade_request,
            state=state,
            req_id=req_id,
            stake=stake,
            duration=duration,
            duration_unit=duration_unit,
        )
    barrier = trade_request.get("barrier")
    requested_barrier = barrier
    req_meta = dict(trade_request.get("req_meta") or {})
    mode = _deriv_trade_connection_mode(state)
    account_type = "demo" if _oauth_account_is_demo({"account_id": state.get("deriv_account_id")}) else "real"
    debug = {
        "button": trade_request.get("button") or trade_request.get("strategy_name"),
        "profile": trade_request.get("profile"),
        "connection_mode": mode,
        "account_id": state.get("deriv_account_id"),
        "account_type": account_type,
        "ws_ready_state": _websocket_ready_state_label(state),
        "otp_authenticated": _is_otp_authenticated_socket(state),
        "requested_symbol": requested_symbol,
        "requested_contract_type": requested_contract,
        "deriv_contract_type": deriv_contract,
        "requested_barrier": requested_barrier,
    }

    underlying_symbol = requested_symbol
    if _uses_new_deriv_trade_api(state):
        logger.info(
            "[%s] auth_state_before_trade profile=%s button=%s connection_mode=%s account_id=%s account_type=%s ws_ready_state=%s otp_authenticated=%s",
            client_id,
            trade_request.get("profile") or state.get("active_profile"),
            trade_request.get("button") or trade_request.get("strategy_name") or trade_request.get("mode") or "",
            mode,
            _mask_account_id(state.get("deriv_account_id") or ""),
            account_type,
            _websocket_ready_state_label(state),
            _is_otp_authenticated_socket(state),
        )
        trade_context = trade_request.get("button") or trade_request.get("strategy_name") or trade_request.get("profile") or "trade"
        is_kidgx_trade = str(trade_request.get("mode") or req_meta.get("mode") or "").upper() == "KIDGX"
        underlying_symbol, symbol_err = resolve_new_api_symbol(state, requested_symbol, context=trade_context, client_id=client_id)
        debug["underlying_symbol"] = underlying_symbol
        debug["ws_ready_state"] = _websocket_ready_state_label(state)
        debug["otp_authenticated"] = _is_otp_authenticated_socket(state)
        if symbol_err:
            debug["error"] = symbol_err
            debug["failed_at"] = "symbol_resolver"
            _deriv_trade_debug_log(client_id, "blocked", debug)
            return False, symbol_err
        if is_kidgx_trade:
            logger.info(
                "[%s] kidgx_symbol_resolved profile=%s original_symbol=%s resolved_symbol=%s",
                client_id,
                trade_request.get("profile") or state.get("active_profile"),
                requested_symbol,
                underlying_symbol,
            )
        contracts_for, contracts_err = _get_contracts_for_symbol(client_id, state, underlying_symbol)
        if contracts_err:
            debug["error"] = contracts_err
            debug["failed_at"] = "contracts_for_error"
            _deriv_trade_debug_log(client_id, "blocked", debug)
            return False, contracts_err
        available = _contracts_for_has_contract_type(contracts_for, deriv_contract)
        debug["contract_available"] = bool(available)
        if not available:
            msg = f"Contract type {deriv_contract} is not available for {underlying_symbol}"
            debug["error"] = msg
            debug["failed_at"] = "contract_resolver"
            _deriv_trade_debug_log(client_id, "blocked", debug)
            return False, msg
        if is_kidgx_trade:
            logger.info(
                "[%s] kidgx_contract_resolved profile=%s original_contract_type=%s resolved_contract_type=%s barrier=%s available=%s",
                client_id,
                trade_request.get("profile") or state.get("active_profile"),
                requested_contract,
                deriv_contract,
                barrier,
                bool(available),
            )
        debug["resolved_barrier"] = None
    else:
        debug["underlying_symbol"] = underlying_symbol
        debug["contract_available"] = True
        debug["resolved_barrier"] = barrier

    parameters = {
        "amount": float(stake),
        "basis": "stake",
        "contract_type": deriv_contract,
        "currency": str(trade_request.get("currency") or "USD"),
        "duration": int(duration),
        "duration_unit": duration_unit,
        "symbol": underlying_symbol,
    }
    if barrier not in (None, ""):
        parameters["barrier"] = barrier
    if trade_request.get("barrier2") not in (None, ""):
        parameters["barrier2"] = trade_request.get("barrier2")
    if deriv_contract.startswith("DIGIT") and barrier not in (None, ""):
        try:
            parameters["barrier"] = int(float(barrier))
        except Exception:
            parameters["barrier"] = str(barrier)
    if _uses_new_deriv_trade_api(state):
        original_parameters = dict(parameters)
        parameters, sanitize_err, sanitize_meta = sanitize_new_api_trade_parameters(
            state,
            client_id,
            contracts_for,
            deriv_contract,
            parameters,
            requested_barrier,
            duration,
            duration_unit,
            trade_request.get("button") or trade_request.get("strategy_name") or trade_request.get("profile") or "trade",
        )
        debug["original_payload"] = original_parameters
        debug["sanitized_payload"] = parameters
        debug["resolved_barrier"] = (sanitize_meta or {}).get("resolved_barrier")
        debug["matched_contract"] = (sanitize_meta or {}).get("matched_item")
        removed_fields = (sanitize_meta or {}).get("removed") or {}
        if removed_fields:
            debug["removed_fields"] = ",".join(sorted(removed_fields.keys()))
        if sanitize_err:
            debug["error"] = sanitize_err
            debug["failed_at"] = "parameter_sanitizer"
            _deriv_trade_debug_log(client_id, "blocked", debug)
            logger.info(
                "[%s] auth_state_after_trade profile=%s button=%s connection_mode=%s ws_ready_state=%s otp_authenticated=%s trade_failed_without_disconnect=true failed_at=parameter_sanitizer",
                client_id,
                trade_request.get("profile") or state.get("active_profile"),
                trade_request.get("button") or trade_request.get("strategy_name") or trade_request.get("mode") or "",
                mode,
                _websocket_ready_state_label(state),
                _is_otp_authenticated_socket(state),
            )
            return False, sanitize_err

    req_meta.setdefault("profile", trade_request.get("profile") or state.get("active_profile"))
    req_meta.setdefault("type", requested_contract)
    req_meta.setdefault("contract_type", requested_contract)
    req_meta.setdefault("deriv_contract_type", deriv_contract)
    req_meta["requested_barrier"] = requested_barrier
    req_meta["barrier"] = parameters.get("barrier")
    req_meta["resolved_barrier"] = parameters.get("barrier")
    req_meta.setdefault("stake", float(stake))
    req_meta.setdefault("symbol", requested_symbol)
    req_meta.setdefault("underlying_symbol", underlying_symbol)
    req_meta.setdefault("time", now_time())
    req_meta.setdefault("mode", trade_request.get("mode"))
    req_meta.setdefault("duration", int(duration))
    req_meta.setdefault("duration_unit", duration_unit)
    if trade_request.get("budget_reservation") is not None:
        req_meta.setdefault("budget_reservation", trade_request.get("budget_reservation"))
    state.setdefault("req_meta", {})[req_id] = req_meta
    _stamp_trade_latency(req_meta, "buy_send")

    legacy_payload = {
        "req_id": req_id,
        "buy": 1,
        "price": float(stake),
        "parameters": dict(parameters),
    }
    if _uses_new_deriv_trade_api(state):
        proposal_payload = _proposal_payload_for_connection(state, {"proposal": 1, "req_id": req_id, **parameters})
        debug["proposal_payload"] = proposal_payload
        debug["ws_ready_state"] = _websocket_ready_state_label(state)
        debug["otp_authenticated"] = _is_otp_authenticated_socket(state)
        if str(trade_request.get("mode") or req_meta.get("mode") or "").upper() == "KIDGX":
            logger.info(
                "[%s] kidgx_final_proposal_payload profile=%s payload=%s",
                client_id,
                trade_request.get("profile") or state.get("active_profile"),
                _safe_deriv_payload_text(proposal_payload),
            )
        _deriv_trade_debug_log(client_id, "proposal_send", debug)
        proposal, proposal_err = _request_digit_proposal_for_buy(client_id, state, proposal_payload, timeout_sec=float(trade_request.get("proposal_timeout_sec", 5.0) or 5.0))
        debug["proposal_response"] = proposal or {"error": proposal_err}
        debug["proposal_id"] = (proposal or {}).get("id")
        if str(trade_request.get("mode") or req_meta.get("mode") or "").upper() == "KIDGX":
            logger.info(
                "[%s] kidgx_deriv_response profile=%s stage=proposal response=%s",
                client_id,
                trade_request.get("profile") or state.get("active_profile"),
                _safe_deriv_payload_text(proposal or {"error": proposal_err}),
            )
        if proposal_err:
            debug["error"] = proposal_err
            debug["failed_at"] = "proposal_response"
            _deriv_trade_debug_log(client_id, "proposal_failed", debug)
            logger.info(
                "[%s] auth_state_after_trade profile=%s button=%s connection_mode=%s ws_ready_state=%s otp_authenticated=%s trade_failed_without_disconnect=true failed_at=proposal_response",
                client_id,
                trade_request.get("profile") or state.get("active_profile"),
                trade_request.get("button") or trade_request.get("strategy_name") or trade_request.get("mode") or "",
                mode,
                _websocket_ready_state_label(state),
                _is_otp_authenticated_socket(state),
            )
            try:
                state.get("req_meta", {}).pop(req_id, None)
            except Exception:
                pass
            return False, proposal_err
        proposal_id = (proposal or {}).get("id")
        if proposal_id in (None, ""):
            msg = "Proposal id missing"
            debug["error"] = msg
            debug["failed_at"] = "proposal_id_missing"
            _deriv_trade_debug_log(client_id, "proposal_failed", debug)
            logger.info(
                "[%s] auth_state_after_trade profile=%s button=%s connection_mode=%s ws_ready_state=%s otp_authenticated=%s trade_failed_without_disconnect=true failed_at=proposal_id_missing",
                client_id,
                trade_request.get("profile") or state.get("active_profile"),
                trade_request.get("button") or trade_request.get("strategy_name") or trade_request.get("mode") or "",
                mode,
                _websocket_ready_state_label(state),
                _is_otp_authenticated_socket(state),
            )
            try:
                state.get("req_meta", {}).pop(req_id, None)
            except Exception:
                pass
            return False, msg
        ask_price = _safe_float((proposal or {}).get("ask_price"), _safe_float((proposal or {}).get("display_value"), stake))
        buy_payload = {
            "req_id": req_id,
            "buy": proposal_id,
            "price": float(ask_price if ask_price is not None else stake),
        }
        debug["buy_payload"] = buy_payload
        debug["ws_ready_state"] = _websocket_ready_state_label(state)
        debug["otp_authenticated"] = _is_otp_authenticated_socket(state)
        _deriv_trade_debug_log(client_id, "buy_send", debug)
        try:
            ws.send(json.dumps(buy_payload))
        except Exception as exc:
            debug["error"] = str(exc)
            debug["failed_at"] = "buy_send"
            _deriv_trade_debug_log(client_id, "buy_failed", debug)
            _mark_ws_unhealthy_and_reconnect(client_id, state, "Deriv connection failed while sending a trade. Reconnecting now...")
            try:
                state.get("req_meta", {}).pop(req_id, None)
            except Exception:
                pass
            return False, str(exc)
        logger.info(
            "[%s] auth_state_after_trade profile=%s button=%s connection_mode=%s ws_ready_state=%s otp_authenticated=%s",
            client_id,
            trade_request.get("profile") or state.get("active_profile"),
            trade_request.get("button") or trade_request.get("strategy_name") or trade_request.get("mode") or "",
            mode,
            _websocket_ready_state_label(state),
            _is_otp_authenticated_socket(state),
        )
        return True, "Trade sent"

    if trade_request.get("minimum_profit") not in (None, ""):
        proposal_payload = {"proposal": 1, "req_id": req_id, **parameters}
        debug["proposal_payload"] = proposal_payload
        debug["minimum_profit"] = trade_request.get("minimum_profit")
        _deriv_trade_debug_log(client_id, "legacy_min_profit_proposal_send", debug)
        proposal_req_id, proposal, proposal_err = _request_min_profit_proposal_for_buy(
            client_id,
            state,
            proposal_payload,
            req_meta,
            stake=stake,
            minimum_profit=trade_request.get("minimum_profit"),
            retries=trade_request.get("minimum_profit_retries") or 0,
            buy_best_available=bool(trade_request.get("buy_best_available")),
        )
        debug["proposal_response"] = proposal or {"error": proposal_err}
        debug["proposal_profit"] = _proposal_profit_value(proposal, stake) if proposal else None
        debug["proposal_id"] = (proposal or {}).get("id")
        if proposal_err:
            debug["error"] = proposal_err
            debug["failed_at"] = "minimum_profit_filter"
            _deriv_trade_debug_log(client_id, "legacy_min_profit_blocked", debug)
            try:
                state.get("req_meta", {}).pop(req_id, None)
                state.get("req_meta", {}).pop(str(req_id), None)
            except Exception:
                pass
            return False, proposal_err
        buy_req_id = proposal_req_id or req_id
        debug["buy_payload"] = {"req_id": buy_req_id, "buy": (proposal or {}).get("id")}
        _deriv_trade_debug_log(client_id, "legacy_min_profit_buy_send", debug)
        try:
            return _send_buy_from_proposal(client_id, state, buy_req_id, proposal, stake)
        except Exception as exc:
            debug["error"] = str(exc)
            debug["failed_at"] = "buy_send"
            _deriv_trade_debug_log(client_id, "legacy_min_profit_buy_failed", debug)
            _mark_ws_unhealthy_and_reconnect(client_id, state, "Deriv connection failed while sending a trade. Reconnecting now...")
            try:
                state.get("req_meta", {}).pop(buy_req_id, None)
                state.get("req_meta", {}).pop(str(buy_req_id), None)
            except Exception:
                pass
            return False, str(exc)

    debug["buy_payload"] = legacy_payload
    _deriv_trade_debug_log(client_id, "legacy_buy_send", debug)
    try:
        ws.send(json.dumps(legacy_payload))
        return True, "Trade sent"
    except Exception as exc:
        debug["error"] = str(exc)
        _deriv_trade_debug_log(client_id, "legacy_buy_failed", debug)
        _mark_ws_unhealthy_and_reconnect(client_id, state, "Deriv connection failed while sending a trade. Reconnecting now...")
        try:
            state.get("req_meta", {}).pop(req_id, None)
        except Exception:
            pass
        return False, str(exc)


def _send_trade_payload_with_oauth_proposal(client_id, state, req_id, payload, stake):
    ws = state.get("ws") if isinstance(state, dict) else None
    if not ws:
        return False, "Not connected"
    if _uses_new_deriv_trade_api(state):
        params = dict((payload or {}).get("parameters") or {})
        if not params:
            return False, "Proposal parameters missing"
        logger.info(
            "[%s] deriv_legacy_direct_buy_payload_for_compare payload=%s",
            client_id,
            _safe_deriv_payload_text(payload),
        )
        meta = {}
        try:
            meta = dict((state.get("req_meta") or {}).get(req_id) or (state.get("req_meta") or {}).get(str(req_id)) or {})
        except Exception:
            meta = {}
        return execute_deriv_trade({
            "client_id": client_id,
            "state": state,
            "req_id": req_id,
            "profile": meta.get("profile") or state.get("active_profile"),
            "strategy_name": meta.get("profile") or state.get("active_profile"),
            "contract_type": params.get("contract_type"),
            "stake": stake,
            "symbol": params.get("symbol") or params.get("underlying_symbol"),
            "barrier": params.get("barrier"),
            "duration": params.get("duration"),
            "duration_unit": params.get("duration_unit"),
            "mode": meta.get("mode"),
            "budget_reservation": meta.get("budget_reservation"),
            "req_meta": meta,
        })
    logger.info(
        "[%s] TEMP buy_about_to_be_sent token_type=%s payload=%s",
        client_id,
        _deriv_connection_type(state),
        _safe_deriv_payload_text(payload),
    )
    ws.send(json.dumps(payload))
    logger.info("[%s] TEMP buy_actually_sent req_id=%s token_type=%s", client_id, req_id, _deriv_connection_type(state))
    return True, "Trade sent"


def _oauth_account_is_demo(account):
    account = account or {}
    account_id = str(account.get("account_id") or account.get("loginid") or account.get("id") or "").upper()
    account_type = str(account.get("account_type") or account.get("type") or account.get("landing_company") or "").lower()
    group = str(account.get("group") or account.get("account_group") or "").lower()
    if bool(account.get("is_virtual") or account.get("demo") or account.get("is_demo")):
        return True
    return (
        account_id.startswith("VRTC")
        or "demo" in account_type
        or "virtual" in account_type
        or group in {"demo", "virtual"}
    )


def _oauth_account_label(account):
    return "Demo" if _oauth_account_is_demo(account) else "Real"


def _mask_account_id(account_id):
    account_id = str(account_id or "").strip()
    if len(account_id) <= 6:
        return account_id
    return f"{account_id[:3]}...{account_id[-3:]}"


def _request_options_authenticated_ws_url(client_id, token, account_id, app_id=None, source="oauth"):
    """OAuth Options accounts use REST Bearer auth to get a one-time authenticated WebSocket URL."""
    account_id = str(account_id or "").strip()
    if not account_id:
        raise RuntimeError("Deriv Options account ID is required for OAuth trading")
    app_id = str(app_id or DERIV_OAUTH_APP_ID or DERIV_APP_ID or "1089").strip() or "1089"

    endpoint = DERIV_OPTIONS_OTP_ENDPOINT_TEMPLATE.format(account_id=account_id)
    req = urllib.request.Request(
        endpoint,
        data=b"",
        method="POST",
        headers={
            "Deriv-App-ID": app_id,
            "Authorization": f"Bearer {str(token or '').strip()}",
            "Accept": "application/json",
            "User-Agent": "Mozilla/5.0",
        },
    )
    logger.info(
        "[%s] deriv_options_otp_request source=%s account_id=%s account_kind=%s token=%s app_id=%s",
        client_id,
        source,
        _mask_account_id(account_id),
        "demo" if _oauth_account_is_demo({"account_id": account_id}) else "real",
        _mask_api_token(token),
        app_id,
    )
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            status = getattr(resp, "status", 200)
            body = resp.read().decode("utf-8", errors="replace")
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        message = _extract_deriv_rest_error(body)
        logger.warning(
            "[%s] deriv_options_otp_failed source=%s status=%s account_id=%s response_text=%s",
            client_id,
            source,
            exc.code,
            _mask_account_id(account_id),
            _sanitize_deriv_oauth_response_text(body),
        )
        raise RuntimeError(f"Deriv OTP request failed ({exc.code}): {message}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Deriv OTP request failed: {exc.reason}") from exc

    try:
        payload = json.loads(body or "{}")
    except Exception as exc:
        raise RuntimeError("Deriv OTP request returned invalid JSON") from exc

    url = ((payload.get("data") or {}).get("url") if isinstance(payload.get("data"), dict) else None) or payload.get("url")
    if not url:
        raise RuntimeError("Failed to get Deriv authenticated WebSocket URL")
    logger.info(
        "[%s] deriv_options_otp_success source=%s status=%s account_id=%s websocket_type=%s",
        client_id,
        source,
        status,
        _mask_account_id(account_id),
        "demo" if _oauth_account_is_demo({"account_id": account_id}) else "real",
    )
    return str(url)


def _request_oauth_options_ws_url(client_id, token, account_id, app_id=None):
    return _request_options_authenticated_ws_url(client_id, token, account_id, app_id=app_id or DERIV_OAUTH_APP_ID, source="oauth")


def _base64url_no_padding(raw_bytes):
    return base64.urlsafe_b64encode(raw_bytes).decode("ascii").rstrip("=")


def _derive_oauth_redirect_uri():
    return DERIV_OAUTH_REDIRECT_URI


def _generate_deriv_oauth_pkce():
    verifier = _base64url_no_padding(secrets.token_bytes(48))
    challenge = _base64url_no_padding(hashlib.sha256(verifier.encode("ascii")).digest())
    state_value = secrets.token_urlsafe(32)
    return verifier, challenge, state_value


def _deriv_oauth_login_url(code_challenge, state_value, redirect_uri):
    params = {
        "response_type": "code",
        "client_id": DERIV_OAUTH_CLIENT_ID,
        "redirect_uri": redirect_uri,
        "scope": DERIV_OAUTH_SCOPE,
        "state": state_value,
        "code_challenge": code_challenge,
        "code_challenge_method": "S256",
    }
    login_url = f"{DERIV_OAUTH_AUTH_URL}?{urllib.parse.urlencode(params)}"
    safe_params = dict(params)
    safe_params["state"] = "<generated>"
    safe_params["code_challenge"] = "<generated_pkce_challenge>"
    logger.info(
        "[oauth] deriv_oauth_login_url_generated base=%s redirect_uri=%s safe_url=%s?%s",
        DERIV_OAUTH_AUTH_URL,
        redirect_uri,
        DERIV_OAUTH_AUTH_URL,
        urllib.parse.urlencode(safe_params),
    )
    return login_url


def _exchange_deriv_oauth_code(code, code_verifier, redirect_uri):
    form = {
        "grant_type": "authorization_code",
        "client_id": DERIV_OAUTH_CLIENT_ID,
        "code": code,
        "code_verifier": code_verifier,
        "redirect_uri": redirect_uri,
    }
    body = urllib.parse.urlencode(form).encode("utf-8")
    req = urllib.request.Request(
        DERIV_OAUTH_TOKEN_URL,
        data=body,
        method="POST",
        headers={
            "Content-Type": "application/x-www-form-urlencoded",
            "Accept": "application/json",
            "User-Agent": "Mozilla/5.0",
        },
    )
    logger.info("[oauth] backend_token_exchange_start endpoint=%s redirect_uri=%s", DERIV_OAUTH_TOKEN_URL, redirect_uri)
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            status_code = getattr(resp, "status", 200)
            body_text = resp.read().decode("utf-8", errors="replace")
            logger.info(
                "[oauth] backend_token_exchange_response endpoint=%s status=%s response_text=%s",
                DERIV_OAUTH_TOKEN_URL,
                status_code,
                _sanitize_deriv_oauth_response_text(body_text),
            )
            payload = json.loads(body_text or "{}")
    except urllib.error.HTTPError as exc:
        body_text = exc.read().decode("utf-8", errors="replace")
        logger.warning(
            "[oauth] backend_token_exchange_response endpoint=%s status=%s response_text=%s",
            DERIV_OAUTH_TOKEN_URL,
            exc.code,
            _sanitize_deriv_oauth_response_text(body_text),
        )
        raise RuntimeError(f"Deriv OAuth token exchange failed ({exc.code}): {_extract_deriv_rest_error(body_text)}") from exc
    except urllib.error.URLError as exc:
        logger.warning("[oauth] backend_token_exchange_transport_error endpoint=%s error=%s", DERIV_OAUTH_TOKEN_URL, exc.reason)
        raise RuntimeError(f"Deriv OAuth token exchange failed: {exc.reason}") from exc
    token = str(payload.get("access_token") or "").strip()
    if not token:
        raise RuntimeError("Deriv OAuth did not return an access token")
    return payload


def _normalize_deriv_options_account(item):
    if not isinstance(item, dict):
        return None
    account_id = str(
        item.get("account_id")
        or item.get("loginid")
        or item.get("id")
        or item.get("account")
        or ""
    ).strip()
    if not account_id:
        return None
    entry = {
        "account_id": account_id,
        "currency": str(item.get("currency") or "").strip(),
        "account_type": str(item.get("account_type") or item.get("type") or item.get("landing_company") or "").strip(),
        "group": str(item.get("group") or item.get("account_group") or "").strip(),
        "is_virtual": _oauth_account_is_demo(item),
    }
    entry["account_kind"] = _oauth_account_label(entry)
    return entry


def _fetch_deriv_oauth_accounts(access_token, allow_empty=False):
    req = urllib.request.Request(
        DERIV_ACCOUNTS_URL,
        method="GET",
        headers={
            "Deriv-App-ID": DERIV_OAUTH_APP_ID,
            "Authorization": f"Bearer {access_token}",
            "Accept": "application/json",
            "User-Agent": "Mozilla/5.0",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            status_code = getattr(resp, "status", 200)
            body_text = resp.read().decode("utf-8", errors="replace")
            logger.info("[oauth] deriv_oauth_accounts_response status=%s response_text=%s", status_code, _sanitize_deriv_oauth_response_text(body_text))
            payload = json.loads(body_text or "{}")
    except urllib.error.HTTPError as exc:
        body_text = exc.read().decode("utf-8", errors="replace")
        logger.warning("[oauth] deriv_oauth_accounts_response status=%s response_text=%s", exc.code, _sanitize_deriv_oauth_response_text(body_text))
        raise RuntimeError(f"Deriv account list failed ({exc.code}): {_extract_deriv_rest_error(body_text)}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Deriv account list failed: {exc.reason}") from exc
    raw_accounts = payload.get("data") or payload.get("accounts") or []
    if isinstance(raw_accounts, dict):
        candidates = []
        for key in ("accounts", "data", "demo", "real", "virtual", "trading_accounts"):
            value = raw_accounts.get(key)
            if isinstance(value, list):
                candidates.extend(value)
            elif isinstance(value, dict):
                candidates.extend([v for v in value.values() if isinstance(v, dict)])
        if not candidates:
            candidates.extend([v for v in raw_accounts.values() if isinstance(v, dict)])
        raw_accounts = candidates
    accounts = []
    if isinstance(raw_accounts, list):
        for item in raw_accounts:
            if not isinstance(item, dict):
                continue
            entry = _normalize_deriv_options_account(item)
            if entry:
                accounts.append(entry)
    if not accounts and allow_empty:
        logger.info("[oauth] deriv_oauth_accounts_returned count=0 demo=0 real=0 app_id=%s", DERIV_OAUTH_APP_ID)
        return []
    if not accounts:
        raise RuntimeError("No Deriv accounts were returned for this login")
    demo_count = sum(1 for account in accounts if _oauth_account_is_demo(account))
    logger.info(
        "[oauth] deriv_oauth_accounts_returned count=%s demo=%s real=%s app_id=%s",
        len(accounts),
        demo_count,
        max(0, len(accounts) - demo_count),
        DERIV_OAUTH_APP_ID,
    )
    return accounts


def _serialize_broadcast_notice(notice):
    if not notice:
        return None
    expires_at_ts = notice.get("expires_at_ts")
    remaining_sec = None
    if expires_at_ts:
        remaining_sec = max(0, int(float(expires_at_ts) - time.time()))
    return {
        "active": True,
        "id": notice.get("id"),
        "message": notice.get("message") or "",
        "type": notice.get("type") or "info",
        "created_at": notice.get("created_at"),
        "expires_at": notice.get("expires_at"),
        "remaining_sec": remaining_sec,
    }


def get_active_broadcast_notice():
    global ACTIVE_BROADCAST_NOTICE
    with BROADCAST_NOTICE_LOCK:
        notice = ACTIVE_BROADCAST_NOTICE
        if not notice:
            return None
        expires_at_ts = notice.get("expires_at_ts")
        if expires_at_ts and time.time() >= float(expires_at_ts):
            ACTIVE_BROADCAST_NOTICE = None
            logger.info("Admin broadcast notice auto-cleared after expiry")
            return None
        return _serialize_broadcast_notice(notice)


def set_active_broadcast_notice(message, notice_type="info", duration_minutes=None, admin_user=None):
    global ACTIVE_BROADCAST_NOTICE
    clean_message = str(message or "").strip()
    if not clean_message:
        return False, "Message is required", None
    clean_type = str(notice_type or "info").strip().lower()
    if clean_type not in BROADCAST_NOTICE_TYPES:
        clean_type = "info"

    expires_at_ts = None
    expires_at = None
    if duration_minutes not in (None, ""):
        try:
            minutes = float(duration_minutes)
        except Exception:
            return False, "Duration must be a number of minutes", None
        if minutes <= 0:
            return False, "Duration must be greater than 0 minutes", None
        expires_at_ts = time.time() + (minutes * 60)
        expires_at = datetime.utcfromtimestamp(expires_at_ts).strftime("%Y-%m-%d %H:%M:%S")

    notice = {
        "id": uuid.uuid4().hex[:12],
        "message": clean_message,
        "type": clean_type,
        "created_at": _utc_now_str(),
        "expires_at": expires_at,
        "expires_at_ts": expires_at_ts,
    }
    with BROADCAST_NOTICE_LOCK:
        ACTIVE_BROADCAST_NOTICE = notice
    payload = _serialize_broadcast_notice(notice)
    socketio.emit("broadcast_notice", payload)
    logger.info(
        "Admin broadcast notice sent by %s type=%s duration_minutes=%s",
        admin_user or "admin",
        clean_type,
        duration_minutes if duration_minutes not in (None, "") else "none",
    )
    return True, "Broadcast notice sent", payload


def clear_active_broadcast_notice(admin_user=None):
    global ACTIVE_BROADCAST_NOTICE
    with BROADCAST_NOTICE_LOCK:
        ACTIVE_BROADCAST_NOTICE = None
    socketio.emit("broadcast_notice", {"active": False})
    logger.info("Admin broadcast notice cleared by %s", admin_user or "admin")
    return True, "Broadcast notice cleared"

