# ---------------- DATABASE + LICENSE/AUTH SETUP ---------------- #
def _db_is_postgres():
    return DB_BACKEND == "postgres"


def _db_connect(row_factory=False):
    if _db_is_postgres():
        return psycopg2.connect(DATABASE_URL)
    conn = sqlite3.connect(DB_FILE)
    if row_factory:
        conn.row_factory = sqlite3.Row
    return conn


def _db_execute(cursor, sql, params=()):
    if _db_is_postgres():
        sql = sql.replace("?", "%s")
    return cursor.execute(sql, params)


def _db_fetchone(cursor):
    return cursor.fetchone()


def _db_commit(conn):
    try:
        conn.commit()
    except Exception:
        pass


def _table_has_column_sqlite(conn, table_name, column_name):
    c = conn.cursor()
    c.execute(f"PRAGMA table_info({table_name})")
    cols = {row[1] for row in c.fetchall()}
    return column_name in cols


def _db_row_to_dict(cursor, row):
    if row is None:
        return None
    try:
        if hasattr(row, "keys"):
            return {k: row[k] for k in row.keys()}
    except Exception:
        pass
    try:
        cols = [d[0] for d in (cursor.description or [])]
        return {cols[i]: row[i] for i in range(min(len(cols), len(row)))}
    except Exception:
        return None


def _db_fetchall_dicts(cursor):
    rows = cursor.fetchall()
    return [(_db_row_to_dict(cursor, r) or {}) for r in (rows or [])]


def _utc_now_str():
    return datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S")


def _parse_dt(value):
    if not value:
        return None
    if isinstance(value, datetime):
        return value
    s = str(value).strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S"):
        try:
            return datetime.strptime(s[:19], fmt)
        except Exception:
            pass
    return None


def normalize_license_key(key):
    return str(key or "").strip().upper().replace(" ", "")


def _db_add_user_column_if_missing(conn, column_name, column_def_sql):
    if _db_is_postgres():
        cur = conn.cursor()
        cur.execute(f"ALTER TABLE users ADD COLUMN IF NOT EXISTS {column_name} {column_def_sql}")
        return
    if not _table_has_column_sqlite(conn, "users", column_name):
        cur = conn.cursor()
        cur.execute(f"ALTER TABLE users ADD COLUMN {column_name} {column_def_sql}")


def _db_create_auth_tables(conn):
    c = conn.cursor()
    if _db_is_postgres():
        c.execute("""
        CREATE TABLE IF NOT EXISTS licenses (
            license_key TEXT PRIMARY KEY,
            license_type TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'active',
            created_at TIMESTAMP NOT NULL,
            activated_at TIMESTAMP NULL,
            expires_at TIMESTAMP NULL,
            used_by TEXT NULL
        )
        """)
        c.execute("""
        CREATE TABLE IF NOT EXISTS password_resets (
            id BIGSERIAL PRIMARY KEY,
            username TEXT NOT NULL,
            token_hash TEXT NOT NULL UNIQUE,
            created_at TIMESTAMP NOT NULL,
            expires_at TIMESTAMP NOT NULL,
            used_at TIMESTAMP NULL
        )
        """)
        c.execute("""
        CREATE TABLE IF NOT EXISTS custom_ui_settings (
            username TEXT PRIMARY KEY,
            settings_json TEXT NOT NULL,
            updated_at TIMESTAMP NOT NULL
        )
        """)
    else:
        c.execute("""
        CREATE TABLE IF NOT EXISTS licenses (
            license_key TEXT PRIMARY KEY,
            license_type TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'active',
            created_at TEXT NOT NULL,
            activated_at TEXT,
            expires_at TEXT,
            used_by TEXT
        )
        """)
        c.execute("""
        CREATE TABLE IF NOT EXISTS password_resets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            token_hash TEXT NOT NULL UNIQUE,
            created_at TEXT NOT NULL,
            expires_at TEXT NOT NULL,
            used_at TEXT
        )
        """)
        c.execute("""
        CREATE TABLE IF NOT EXISTS custom_ui_settings (
            username TEXT PRIMARY KEY,
            settings_json TEXT NOT NULL,
            updated_at TEXT NOT NULL
        )
        """)
    ensure_cloud_tables(conn, is_postgres=_db_is_postgres())


def init_db():
    conn = _db_connect()
    c = conn.cursor()

    if _db_is_postgres():
        c.execute("""
        CREATE TABLE IF NOT EXISTS users (
            id BIGSERIAL PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL
        )
        """)
    else:
        c.execute("""
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL
        )
        """)

    # Safe migrations for auth/license support
    _db_add_user_column_if_missing(conn, "email", "TEXT")
    _db_add_user_column_if_missing(conn, "role", "TEXT DEFAULT 'user'")
    _db_add_user_column_if_missing(conn, "grandfathered", "INTEGER DEFAULT 1")
    _db_add_user_column_if_missing(conn, "license_key", "TEXT")
    _db_add_user_column_if_missing(conn, "license_exempt", "INTEGER DEFAULT 0")
    _db_add_user_column_if_missing(conn, "created_at", "TEXT")

    _db_create_auth_tables(conn)

    now_s = _utc_now_str()
    _db_execute(c, "UPDATE users SET role='user' WHERE role IS NULL OR TRIM(role)=''", ())
    _db_execute(c, "UPDATE users SET grandfathered=1 WHERE grandfathered IS NULL", ())
    _db_execute(c, "UPDATE users SET license_exempt=0 WHERE license_exempt IS NULL", ())
    _db_execute(c, "UPDATE users SET created_at=? WHERE created_at IS NULL OR TRIM(created_at)=''", (now_s,))
    _db_commit(conn)
    conn.close()


def _maybe_migrate_sqlite_users_to_postgres():
    # One-time migration for Render deployment/local cutover: if an older local
    # SQLite auth DB exists (user.db or users.db), import it into Postgres
    # without changing the live login/register UI behavior.
    if not _db_is_postgres():
        return
    sqlite_path = find_existing_sqlite_auth_db(default_name=DB_FILE)
    if not sqlite_path:
        return
    try:
        counts = migrate_sqlite_auth_to_postgres(sqlite_path=sqlite_path, database_url=DATABASE_URL)
        logger.info(
            "SQLite -> Postgres migration checked "
            f"(source={counts.get('sqlite_path')}, users={counts.get('users')}, "
            f"licenses={counts.get('licenses')}, resets={counts.get('password_resets')})"
        )
    except Exception as e:
        logger.error(f"SQLite -> Postgres migration failed: {e}")


def ensure_admin_user():
    conn = _db_connect()
    c = conn.cursor()
    _db_execute(c, "SELECT id FROM users WHERE lower(username)=lower(?)", (ADMIN_USERNAME,))
    exists = _db_fetchone(c)

    if not exists:
        hashed_pw = generate_password_hash(ADMIN_PASSWORD)
        _db_execute(
            c,
            """
            INSERT INTO users (username, password, role, grandfathered, license_exempt, created_at)
            VALUES (?, ?, 'admin', 1, 1, ?)
            """,
            (ADMIN_USERNAME, hashed_pw, _utc_now_str()),
        )
        _db_commit(conn)
        print(f"✅ Admin account created automatically: {ADMIN_USERNAME}")
    else:
        _db_execute(
            c,
            """
            UPDATE users SET role='admin', grandfathered=1, license_exempt=1,
                   created_at=COALESCE(created_at, ?)
             WHERE lower(username)=lower(?)
            """,
            (_utc_now_str(), ADMIN_USERNAME),
        )
        _db_commit(conn)
    conn.close()


def get_user_count():
    conn = _db_connect()
    c = conn.cursor()
    _db_execute(c, "SELECT COUNT(*) FROM users WHERE lower(username) != lower(?)", (ADMIN_USERNAME,))
    row = _db_fetchone(c)
    conn.close()
    return int((row[0] if row else 0) or 0)


def _get_user_row(username):
    identifier = (username or "").strip()
    if not identifier:
        return None
    conn = _db_connect(row_factory=not _db_is_postgres())
    c = conn.cursor()
    _db_execute(
        c,
        "SELECT * FROM users WHERE lower(username)=lower(?) OR lower(COALESCE(email,''))=lower(?) LIMIT 1",
        (identifier, identifier),
    )
    row = _db_fetchone(c)
    out = _db_row_to_dict(c, row)
    conn.close()
    return out


def _request_host_is_local():
    host = str(getattr(request, "host", "") or "").split(":", 1)[0].strip().strip("[]").lower()
    if not host:
        return False
    if host in {"localhost", "::1"}:
        return True
    try:
        ip = ipaddress.ip_address(host)
        return bool(ip.is_loopback or ip.is_private)
    except ValueError:
        return host.endswith(".local")


def _current_user_mutant_identity():
    username = str(session.get("user") or "").strip().lower()
    if not username:
        return {"username": "", "email": ""}
    user_row = _get_user_row(username) or {}
    return {
        "username": username,
        "email": str(user_row.get("email") or "").strip().lower(),
    }


def _mutant_access_state():
    local_request = _request_host_is_local()
    identity = _current_user_mutant_identity()
    allowed_account = MUTANT_ALLOWED_ACCOUNT
    username_override = bool(
        allowed_account and identity.get("username") and identity.get("username") == allowed_account
    )
    email_override = bool(
        allowed_account and identity.get("email") and identity.get("email") == allowed_account
    )
    return {
        "enabled": True,
        "under_construction": False,
        "local": bool(local_request),
        "username_override": bool(username_override),
        "email_override": bool(email_override),
        "user_username": identity.get("username") or "",
        "user_email": identity.get("email") or "",
        "message": "",
    }


def _mutant_under_construction_response(status_code=423):
    access = _mutant_access_state()
    return (
        jsonify({
            "status": "error",
            "message": access.get("message") or MUTANT_UNDER_CONSTRUCTION_MESSAGE,
            "mutant_access": access,
        }),
        status_code,
    )


