# ---------------- HELPERS ---------------- #
def login_required():
    username = session.get("user")
    if not username:
        return False
    user_row = _get_user_row(username)
    if not user_row:
        return False
    ok, _msg = check_user_license_access(user_row)
    return bool(ok)


def is_admin():
    if str(session.get("role") or "").lower() == "admin":
        return True
    user_row = _get_user_row(session.get("user"))
    return bool(user_row and str(user_row.get("role") or "").lower() == "admin")


def get_client_id():
    """
    Each browser / device gets its own client_id in the Flask session.
    Same username on 2 devices => 2 different client_ids => 2 independent bots.
    """
    cid = session.get("client_id")
    if not cid:
        cid = str(uuid.uuid4())
        session["client_id"] = cid
    return cid


def _new_req_id():
    return int(uuid.uuid4().int % 1000000000)


TRADE_LATENCY_LOG_ENABLED = str(os.getenv("TRADE_LATENCY_LOG_ENABLED", "0")).strip().lower() in ("1", "true", "yes", "on")
FAST_CONTRACT_REFRESH_DELAYS = (0.03, 0.10, 0.22, 0.45, 0.9, 1.8, 3.2)
DEFAULT_CONTRACT_REFRESH_DELAYS = (0.18, 0.55, 1.45, 3.2)
UI_TICK_EMIT_MIN_SEC = 0.06
UI_ANALYSIS_EMIT_MIN_SEC = 0.10
UI_STATUS_EMIT_MIN_SEC = 0.12
UI_HUMAN_CHART_EMIT_MIN_SEC = 0.12


def _trade_latency_now():
    try:
        return time.monotonic()
    except Exception:
        return time.time()


def _stamp_trade_latency(meta, stage):
    if not isinstance(meta, dict):
        return
    timings = meta.setdefault("_latency", {})
    try:
        timings[stage] = _trade_latency_now()
    except Exception:
        pass


def _log_trade_latency(client_id, meta, stage, **extra):
    if not TRADE_LATENCY_LOG_ENABLED or not isinstance(meta, dict):
        return
    try:
        timings = meta.get("_latency") or {}
        sent_at = timings.get("buy_send")
        elapsed_ms = None
        if sent_at is not None:
            elapsed_ms = round((_trade_latency_now() - float(sent_at)) * 1000.0, 1)
        logger.info(
            "[%s] trade_latency stage=%s profile=%s type=%s contract_id=%s elapsed_ms=%s extra=%s",
            client_id,
            stage,
            meta.get("profile"),
            meta.get("type") or meta.get("contract_type"),
            extra.get("contract_id"),
            elapsed_ms,
            {k: v for k, v in extra.items() if k != "contract_id"},
        )
    except Exception:
        pass


def _is_fast_contract_meta(meta):
    if not isinstance(meta, dict):
        return False
    try:
        duration = int(float(meta.get("duration") or 0))
    except Exception:
        duration = 0
    duration_unit = str(meta.get("duration_unit") or "t").strip().lower()
    trade_type = str(meta.get("type") or meta.get("contract_type") or "").upper()
    mode = str(meta.get("mode") or "").upper()
    if "TURBO" in mode:
        return True
    if duration_unit == "t" and 0 < duration <= 3:
        return True
    if duration_unit == "s" and 0 < duration <= 3:
        return True
    return trade_type in ("OVER", "UNDER", "MATCHES", "DIFFERS", "DIGITOVER", "DIGITUNDER", "DIGITMATCH", "DIGITDIFF") and duration_unit == "t" and duration <= 5


def _contract_refresh_delays_for_meta(meta):
    base_delays = FAST_CONTRACT_REFRESH_DELAYS if _is_fast_contract_meta(meta) else DEFAULT_CONTRACT_REFRESH_DELAYS
    try:
        duration = int(float((meta or {}).get("duration") or 0))
    except Exception:
        duration = 0
    duration_unit = str((meta or {}).get("duration_unit") or "t").strip().lower()
    if duration <= 1:
        return base_delays

    extra_delays = ()
    # Tick contracts can settle after the first short fallback window,
    # especially on Render when subscription messages lag. Keep a few absolute
    # refreshes past the expected expiry so pending history rows can self-heal.
    if duration_unit == "t":
        extra_delays = (
            min(18.0, (duration * 1.5) + 2.0),
            min(36.0, (duration * 3.0) + 5.0),
        )
    elif duration_unit == "s":
        # Second-based contracts need refreshes past their wall-clock expiry;
        # otherwise 15-30s rows can stay pending if the subscription update lags.
        extra_delays = (
            min(45.0, duration + 0.75),
            min(50.0, duration + 2.0),
            min(60.0, duration + 6.0),
        )
    else:
        return base_delays

    merged = []
    for value in tuple(base_delays) + extra_delays:
        try:
            delay = round(max(0.0, float(value)), 3)
        except Exception:
            continue
        if delay not in merged:
            merged.append(delay)
    return tuple(sorted(merged))


def _should_emit_ui_event(state, key, min_interval_sec):
    if not isinstance(state, dict):
        return True
    now = _trade_latency_now()
    emit_at = state.setdefault("_ui_emit_last_at", {})
    try:
        last = float(emit_at.get(key, 0.0) or 0.0)
    except Exception:
        last = 0.0
    if last and (now - last) < max(0.0, float(min_interval_sec or 0.0)):
        return False
    emit_at[key] = now
    return True


def _touch_client(client_id):
    st = clients.get(client_id)
    if st:
        st["last_seen"] = time.time()


def _get_ws_lifecycle_lock(state):
    lock = None
    try:
        lock = state.get("ws_lifecycle_lock")
    except Exception:
        lock = None
    if lock is None:
        lock = threading.RLock()
        try:
            state["ws_lifecycle_lock"] = lock
        except Exception:
            pass
    return lock


def _cleanup_client_runtime(client_id, state, reason="cleanup"):
    if not state:
        return
    logger.info(
        "[%s] client_runtime_cleanup_start reason=%s active_clients=%s active_threads=%s",
        client_id,
        reason,
        len(clients),
        threading.active_count(),
    )
    try:
        state["ws_stop_event"].set()
    except Exception:
        pass
    try:
        ping_stop = state.get("ws_ping_stop_event")
        if ping_stop:
            ping_stop.set()
    except Exception:
        pass
    try:
        ws = state.get("ws")
        if ws:
            ws.close()
    except Exception:
        logger.exception("[%s] client_runtime_cleanup_ws_close_failed reason=%s", client_id, reason)
    try:
        _stop_unchain_scanner_worker(state)
    except Exception:
        pass
    try:
        _cleanup_koolkid_golden_card_subscriptions(state)
    except Exception:
        pass
    try:
        for timer in list((state.get("bot_auto_close_timers") or {}).values()):
            try:
                timer.cancel()
            except Exception:
                pass
        state["bot_auto_close_timers"] = {}
    except Exception:
        pass
    for key in (
        "tick_subs",
        "open_contract_subs",
        "req_meta",
        "_proposal_waiters",
        "contract_meta",
        "human_pending_contracts",
    ):
        try:
            value = state.get(key)
            if isinstance(value, dict):
                value.clear()
            else:
                state[key] = {}
        except Exception:
            pass
    try:
        state["ws"] = None
        state["ws_connected"] = False
        state["ws_transport_connected"] = False
        state["ws_connect_started_at"] = 0.0
        state["ws_authorize_deadline_at"] = 0.0
        state["ws_reconnect_pending"] = False
        state["pat_otp_ws_url"] = ""
        state["pat_otp_reconnect_used"] = False
    except Exception:
        pass
    logger.info(
        "[%s] client_runtime_cleanup_done reason=%s active_clients=%s active_threads=%s",
        client_id,
        reason,
        len(clients),
        threading.active_count(),
    )


def _start_ws_worker_thread(client_id, state, reason="start"):
    if not state:
        return None
    lock = _get_ws_lifecycle_lock(state)
    with lock:
        existing = state.get("ws_thread")
        if existing and existing.is_alive():
            logger.info("[%s] websocket_existing_worker_stopping reason=%s", client_id, reason)
            try:
                state["ws_stop_event"].set()
            except Exception:
                pass
            try:
                ping_stop = state.get("ws_ping_stop_event")
                if ping_stop:
                    ping_stop.set()
            except Exception:
                pass
            try:
                ws = state.get("ws")
                if ws:
                    ws.close()
            except Exception:
                pass
        thread_name = f"deriv_ws_{client_id}_{str(reason or 'start')[:32]}"
        t = threading.Thread(target=start_ws_for_client, args=(client_id,), daemon=True, name=thread_name)
        state["ws_thread"] = t
        t.start()
        logger.info(
            "[%s] websocket_worker_spawned reason=%s active_clients=%s active_threads=%s",
            client_id,
            reason,
            len(clients),
            threading.active_count(),
        )
        return t


def _hard_stop_all_strategies(state):
    """
    Your rule: when API disconnected -> everything stops (auto + memory).
    We reset strategies and force all auto flags OFF safely.
    """
    for strat in state.get("strategies", {}).values():
        try:
            strat.reset()
        except Exception:
            pass

        # force common auto flags off
        if hasattr(strat, "auto_trade"):
            try:
                strat.auto_trade = False
            except Exception:
                pass

        # JokerJoe extra autos (safe)
        for k in ("sludgex_auto", "triplex_auto", "kidx_auto", "multig_auto"):
            if hasattr(strat, k):
                try:
                    setattr(strat, k, False)
                except Exception:
                    pass


PROFILE_BUDGET_KEYS = ("KOOLKID", "JOKERJOE", "HUMAN", "UNCHAIN", "NTT", "CLOUD")


def _normalize_profile_budget_key(profile):
    key = str(profile or "").upper().strip()
    if key in PROFILE_BUDGET_KEYS:
        return key
    return "KOOLKID"


def _new_profile_budget_entry():
    return {
        "amount": 0.0,
        "realized_pnl": 0.0,
        "reserved": 0.0,
    }


def _new_profile_budget_map():
    return {key: _new_profile_budget_entry() for key in PROFILE_BUDGET_KEYS}


def _safe_money(value, default=0.0):
    try:
        return float(value or 0.0)
    except Exception:
        return float(default or 0.0)


def _ensure_profile_budgets(state):
    budgets = state.get("profile_budgets")
    if not isinstance(budgets, dict):
        budgets = {}
        state["profile_budgets"] = budgets
    for key in PROFILE_BUDGET_KEYS:
        entry = budgets.get(key)
        if not isinstance(entry, dict):
            budgets[key] = _new_profile_budget_entry()
            continue
        entry.setdefault("amount", 0.0)
        entry.setdefault("realized_pnl", 0.0)
        entry.setdefault("reserved", 0.0)
    return budgets


def _ensure_profile_budget(state, profile):
    budgets = _ensure_profile_budgets(state)
    key = _normalize_profile_budget_key(profile)
    entry = budgets.get(key)
    if not isinstance(entry, dict):
        entry = _new_profile_budget_entry()
        budgets[key] = entry
    entry.setdefault("amount", 0.0)
    entry.setdefault("realized_pnl", 0.0)
    entry.setdefault("reserved", 0.0)
    return entry


def _profile_budget_snapshot(state, profile=None):
    profile_key = _normalize_profile_budget_key(profile or state.get("active_profile"))
    entry = _ensure_profile_budget(state, profile_key)
    configured_budget = _effective_trade_balance(entry.get("amount", 0.0))
    realized_pnl = round(_safe_money(entry.get("realized_pnl", 0.0)), 2)
    reserved = _effective_trade_balance(entry.get("reserved", 0.0))
    total_balance = _get_live_account_balance(state)
    enabled = configured_budget > 0.0

    if enabled:
        gross_budget = max(0.0, round(configured_budget + realized_pnl, 2))
        capped_budget = gross_budget if total_balance <= 0 else min(total_balance, gross_budget)
        remaining_budget = max(0.0, round(capped_budget - reserved, 2))
        display_balance = remaining_budget
    else:
        gross_budget = total_balance
        remaining_budget = total_balance
        display_balance = total_balance

    return {
        "profile": profile_key,
        "enabled": enabled,
        "configured_budget": configured_budget,
        "realized_pnl": realized_pnl,
        "reserved": reserved,
        "gross_budget": round(gross_budget, 2),
        "remaining_budget": round(remaining_budget, 2),
        "display_balance": round(display_balance, 2),
        "total_balance": round(total_balance, 2),
    }


def _serialize_profile_budgets(state):
    payload = {}
    for key in PROFILE_BUDGET_KEYS:
        payload[key] = _profile_budget_snapshot(state, key)
    return payload


def _format_state_money(state, value, *, signed=False, trim_trailing=False, fallback="—"):
    try:
        amount = float(value)
    except Exception:
        return fallback
    text = f"{abs(amount):.2f}"
    if trim_trailing:
        text = text.rstrip("0").rstrip(".")
    if signed:
        prefix = "+" if amount > 0 else "-" if amount < 0 else ""
    else:
        prefix = "-" if amount < 0 else ""
    return f"{prefix}${text}"


def _build_balance_payload(state, profile=None):
    snapshot = _profile_budget_snapshot(state, profile)
    account_balance = _get_live_account_balance(state)
    effective_balance = _get_effective_state_balance(state)
    return {
        "balance": account_balance,
        "account_balance": account_balance,
        "effective_balance": effective_balance,
        "display_balance": snapshot.get("display_balance", 0.0),
        "total_balance": snapshot.get("total_balance", 0.0),
        "session_start_balance": state.get("session_start_balance"),
        "active_profile": snapshot.get("profile"),
        "active_profile_budget": snapshot,
        "profile_budgets": _serialize_profile_budgets(state),
    }


def _emit_balance_payload(client_id, state):
    payload = _build_balance_payload(state)
    budget = payload.get("active_profile_budget") or {}
    logger.info(
        "[%s] TEMP balance_display_computed live_account=%s effective=%s display=%s total=%s "
        "budget_enabled=%s budget_remaining=%s session_pnl=%s",
        client_id,
        payload.get("account_balance"),
        payload.get("effective_balance"),
        payload.get("display_balance"),
        payload.get("total_balance"),
        budget.get("enabled"),
        budget.get("remaining_budget"),
        budget.get("realized_pnl"),
    )
    socketio.emit("balance_update", payload, room=client_id)


def _check_profile_budget_capacity(state, profile, amount):
    amount_value = max(0.0, _safe_money(amount))
    snapshot = _profile_budget_snapshot(state, profile)
    if not snapshot.get("enabled"):
        return True, None, snapshot
    available = max(0.0, _safe_money(snapshot.get("remaining_budget")))
    if amount_value <= (available + 1e-9):
        return True, None, snapshot
    profile_label = snapshot.get("profile") or _normalize_profile_budget_key(profile)
    message = (
        f"{profile_label} budget limit reached: need {_format_state_money(state, amount_value)}, "
        f"but only {_format_state_money(state, available)} budget remains."
    )
    return False, message, snapshot


def _reserve_profile_budget(state, profile, amount):
    ok, message, snapshot = _check_profile_budget_capacity(state, profile, amount)
    if not ok:
        return False, message, None

    amount_value = max(0.0, _safe_money(amount))
    reservation = {
        "reservation_id": _new_req_id(),
        "profile": _normalize_profile_budget_key(profile),
        "stake": round(amount_value, 2),
        "enabled": bool(snapshot.get("enabled")),
        "released": False,
        "settled": False,
    }
    if reservation["enabled"] and amount_value > 0:
        entry = _ensure_profile_budget(state, reservation["profile"])
        entry["reserved"] = round(max(0.0, _safe_money(entry.get("reserved")) + amount_value), 2)
        logger.info(
            "TEMP session_budget_remaining profile=%s reserved=%s remaining_snapshot=%s",
            reservation["profile"],
            entry["reserved"],
            max(0.0, _safe_money(snapshot.get("remaining_budget")) - amount_value),
        )
    return True, None, reservation


def _release_profile_budget_reservation(state, reservation):
    if not isinstance(reservation, dict):
        return
    if reservation.get("released"):
        return
    if not reservation.get("enabled"):
        reservation["released"] = True
        return
    profile_key = _normalize_profile_budget_key(reservation.get("profile"))
    amount_value = max(0.0, _safe_money(reservation.get("stake")))
    entry = _ensure_profile_budget(state, profile_key)
    entry["reserved"] = round(max(0.0, _safe_money(entry.get("reserved")) - amount_value), 2)
    reservation["released"] = True


def _settle_profile_budget_reservation(state, reservation, profit):
    if not isinstance(reservation, dict):
        return
    if reservation.get("settled"):
        return
    profile_key = _normalize_profile_budget_key(reservation.get("profile"))
    was_enabled = bool(reservation.get("enabled"))
    _release_profile_budget_reservation(state, reservation)
    if not was_enabled:
        reservation["settled"] = True
        return
    entry = _ensure_profile_budget(state, profile_key)
    entry["realized_pnl"] = round(_safe_money(entry.get("realized_pnl")) + _safe_money(profit), 2)
    logger.info(
        "TEMP session_profit_loss_updated profile=%s profit=%s realized_pnl=%s reserved=%s",
        profile_key,
        _safe_money(profit),
        entry.get("realized_pnl"),
        entry.get("reserved"),
    )
    reservation["settled"] = True


