# ---------------- SOCKET.IO CONNECT ---------------- #
@socketio.on("connect")
def handle_connect(auth=None):
    if not login_required():
        return False

    cid, state = get_client_state()
    logger.info(
        "[%s] TEMP socket_connect_runtime server_instance_id=%s process_id=%s runtime_present=%s ws_connected=%s ws_thread_alive=%s",
        cid,
        SERVER_INSTANCE_ID,
        os.getpid(),
        not bool((state.get("last_runtime_diag") or {}).get("client_runtime_missing_before_init")),
        bool(state.get("ws_connected")),
        bool(state.get("ws_thread") and state["ws_thread"].is_alive()),
    )
    join_room(cid)
    active_notice = get_active_broadcast_notice()
    if active_notice:
        socketio.emit("broadcast_notice", active_notice, room=cid)
    warmup_active = _has_active_tick_stream_warmup(state, now_ts=time.time(), client_id=cid)
    authorized = bool(state.get("ws_connected")) and bool(state.get("ws"))
    connected = authorized
    if authorized and not warmup_active and _is_ws_stale(state):
        logger.warning("[%s] api_socket_stale_observed reason=socket_connect_status action=keep_authorized", cid)

    socketio.emit("connection_status", {
        "connected": connected,
        "loginid": state.get("loginid", "UNKNOWN"),
        **_runtime_diag_payload(cid, state),
        **_build_balance_payload(state),
    }, room=cid)

    emit_profile_snapshot(cid)


@socketio.on("client_heartbeat")
def client_heartbeat():
    if not login_required():
        return
    cid, state = get_client_state()
    # get_client_state already touches last_seen
    if state.get("ws_connected"):
        health = _get_tick_stream_health(cid, state, self_heal=True)
        healthy = bool(health.get("tick_stream_healthy"))
        last_emitted_healthy = state.get("tick_stream_last_emitted_healthy")
        if health.get("tick_stream_recovering") or last_emitted_healthy is None or bool(last_emitted_healthy) != healthy:
            state["tick_stream_last_emitted_healthy"] = healthy
            socketio.emit("connection_status", {
                "connected": True,
                "loginid": state.get("loginid", "UNKNOWN"),
                **_connection_trade_ready_payload(state),
                **health,
                **_build_balance_payload(state),
            }, room=cid)
    return


def _is_turbo_requested(payload):
    raw = None
    if isinstance(payload, dict):
        raw = payload.get("turbo")
    if isinstance(raw, str):
        return raw.strip().lower() in ("1", "true", "yes", "on")
    return bool(raw)


def _batch_trade_sleep_seconds(payload, normal_default=0.04):
    if payload and bool((payload or {}).get("same_tick")):
        return 0.0
    if _is_turbo_requested(payload):
        return 0.002
    try:
        return max(0.0, float(normal_default or 0.0))
    except Exception:
        return 0.0


def _trade_extra_meta_from_payload(data, *, leg_action=None):
    payload = data or {}
    extra = {}
    leg = leg_action if leg_action not in (None, "") else payload.get("leg_action")
    if leg not in (None, ""):
        extra["leg_action"] = str(leg).strip()
    if payload.get("hide_from_history") is not None:
        extra["hide_from_history"] = bool(payload.get("hide_from_history"))
    for key in ("batch_id", "batch_label", "batch_stake", "batch_size", "round_number", "strategy_name", "over3_stake", "under6_stake", "minimum_profit", "minimum_profit_retries", "buy_best_available"):
        value = payload.get(key)
        if value not in (None, ""):
            extra[key] = value
    return extra or None


@socketio.on("fast_profile_trade")
def handle_fast_profile_trade(data=None):
    if not login_required():
        return {"status": "error", "message": "Unauthorized"}

    cid, state = get_client_state()
    logger.info(
        "[%s] TEMP backend_received_trade_request source=fast_profile_trade token_type=%s payload=%s",
        cid,
        _deriv_connection_type(state),
        _safe_deriv_payload_text(data or {}),
    )
    return _handle_fast_profile_trade_payload(cid, state, data or {}, emit_balance_after_send=False)


def _handle_fast_profile_trade_payload(client_id, state, payload, *, emit_balance_after_send=False):
    payload = payload or {}
    _log_trade_path(client_id, "fast_profile_payload", state, profile=payload.get("profile"), type=payload.get("type"), symbol=payload.get("symbol"))
    profile = str(payload.get("profile") or state.get("active_profile") or "").upper().strip()
    if profile not in ("KOOLKID", "JOKERJOE", "CLOUD"):
        return {"status": "error", "message": "Invalid profile"}

    contract_type = str(payload.get("type") or "").upper().strip()
    try:
        stake = float(payload.get("stake", 1.0) or 1.0)
    except Exception:
        stake = 1.0
    if not math.isfinite(stake) or stake <= 0:
        stake = 1.0

    symbol = str(payload.get("symbol") or state.get("current_symbol", "R_25") or "R_25").strip() or "R_25"
    try:
        barrier = int(payload.get("barrier", 5))
    except Exception:
        barrier = 5
    duration = _sanitize_digit_trade_duration(payload.get("duration", 1))
    duration_unit = str(payload.get("duration_unit") or "t").strip().lower() or "t"
    if duration_unit not in ("t", "s", "m", "h"):
        duration_unit = "t"
    mode = str(payload.get("mode") or "").strip() or None
    leg_action = str(payload.get("leg_action") or "").strip() or None

    send_kwargs = {
        "duration": duration,
        "duration_unit": duration_unit,
        "mode": mode,
        "emit_balance_after_send": bool(emit_balance_after_send),
    }
    for key in ("minimum_profit", "minimum_profit_retries", "buy_best_available"):
        if payload.get(key) not in (None, ""):
            send_kwargs[key] = payload.get(key)
    extra_meta = _trade_extra_meta_from_payload(payload, leg_action=leg_action)
    if extra_meta:
        send_kwargs["extra_meta"] = extra_meta
    ok, message = send_buy_with_profile(
        client_id,
        profile,
        contract_type,
        stake,
        symbol,
        barrier,
        **send_kwargs,
    )
    return {
        "status": "success" if ok else "error",
        "message": message,
        "profile": profile,
        "type": contract_type,
        "barrier": barrier,
        "leg_action": leg_action,
    }


@socketio.on("fast_profile_trade_batch")
def handle_fast_profile_trade_batch(data=None):
    if not login_required():
        return {"status": "error", "message": "Unauthorized"}

    cid, state = get_client_state()
    payload = data or {}
    profile = str(payload.get("profile") or state.get("active_profile") or "").upper().strip()
    if profile not in ("KOOLKID", "JOKERJOE", "CLOUD"):
        return {"status": "error", "message": "Invalid profile"}

    trades = payload.get("trades")
    if not isinstance(trades, list) or not trades:
        return {"status": "error", "message": "No batch trades supplied", "placed": 0, "responses": []}
    trades = trades[:12]

    responses = []
    placed = 0
    lock = _get_ws_lifecycle_lock(state)
    with lock:
        for index, item in enumerate(trades):
            trade_payload = dict(item or {})
            trade_payload["profile"] = profile
            response = _handle_fast_profile_trade_payload(
                cid,
                state,
                trade_payload,
                emit_balance_after_send=False,
            )
            response["index"] = index
            responses.append(response)
            if response.get("status") == "success":
                placed += 1
    try:
        _emit_balance_payload(cid, state)
    except Exception:
        pass
    return {
        "status": "success" if placed == len(trades) else ("partial" if placed else "error"),
        "message": f"Sent {placed}/{len(trades)} batch trades",
        "profile": profile,
        "placed": placed,
        "responses": responses,
    }


@socketio.on("jokerjoe_blackcard_trade")
def handle_jokerjoe_blackcard_trade(data=None):
    if not login_required():
        return {"status": "error", "message": "Unauthorized"}

    cid, state = get_client_state()
    payload = data or {}

    try:
        digit = int(payload.get("digit"))
    except Exception:
        return {"status": "error", "message": "Pick a valid digit for DIFFERS."}
    if digit < 0 or digit > 9:
        return {"status": "error", "message": "Pick a valid digit for DIFFERS."}

    try:
        stake = float(payload.get("stake", 1.0) or 1.0)
    except Exception:
        stake = 1.0
    if not math.isfinite(stake) or stake <= 0:
        stake = 1.0

    duration = _sanitize_digit_trade_duration(payload.get("duration", 1))
    symbol = str(payload.get("symbol") or state.get("current_symbol", "R_25") or "R_25").strip() or "R_25"

    ok, message = send_buy_with_profile(
        cid,
        "JOKERJOE",
        "DIFFERS",
        stake,
        symbol,
        digit,
        duration=duration,
        duration_unit="t",
        mode="blackcard",
        emit_balance_after_send=False,
    )
    return {
        "status": "success" if ok else "error",
        "message": message,
        "digit": digit,
    }


