def _is_insufficient_funds_error(message):
    text = str(message or "").strip().lower()
    if not text:
        return False
    return (
        "insufficient" in text
        or "not enough balance" in text
        or "not enough funds" in text
        or "insufficient balance" in text
    )


def _effective_trade_balance(balance):
    try:
        value = max(0.0, float(balance or 0.0))
    except Exception:
        value = 0.0
    return round(value + 1e-9, 2)


def _get_effective_state_balance(state):
    if not isinstance(state, dict):
        return 0.0
    current_balance = _effective_trade_balance(_safe_money(state.get("balance", 0.0)))
    last_live_balance = _safe_money(state.get("last_live_balance", 0.0))
    last_known_trade_balance = _safe_money(state.get("last_known_trade_balance", 0.0))
    local_adjustment = _safe_money(state.get("local_balance_adjustment", 0.0))
    live_adjusted_balance = 0.0
    if last_live_balance > 0.0:
        live_adjusted_balance = _effective_trade_balance(last_live_balance + local_adjustment)
    if current_balance > 0.0 and current_balance > (live_adjusted_balance + 0.01):
        return current_balance
    if live_adjusted_balance > 0.0:
        return live_adjusted_balance
    if current_balance > 0.0:
        return current_balance
    if last_known_trade_balance > 0.0:
        if abs(local_adjustment) > 0.009:
            return _effective_trade_balance(last_known_trade_balance + local_adjustment)
        return _effective_trade_balance(last_known_trade_balance)
    return current_balance


def _get_pre_trade_available_balance(state):
    if not isinstance(state, dict):
        return 0.0
    effective_balance = _get_effective_state_balance(state)
    live_balance = _get_live_account_balance(state)
    if live_balance > (effective_balance + 0.01):
        return live_balance
    return effective_balance


def _get_live_account_balance(state):
    """Return the last Deriv account balance without local session adjustments."""
    if not isinstance(state, dict):
        return 0.0
    last_live_balance = _safe_money(state.get("last_live_balance", 0.0))
    if _safe_money(state.get("last_live_balance_updated_at", 0.0)) > 0.0 or last_live_balance > 0.0:
        return _effective_trade_balance(last_live_balance)
    current_balance = _safe_money(state.get("balance", 0.0))
    if _safe_money(state.get("balance_updated_at", 0.0)) > 0.0 or current_balance > 0.0:
        return _effective_trade_balance(current_balance)
    last_known_trade_balance = _safe_money(state.get("last_known_trade_balance", 0.0))
    return _effective_trade_balance(last_known_trade_balance)


def _estimate_profile_open_budget_exposure(state, profile):
    profile_key = _normalize_profile_budget_key(profile)
    total = 0.0

    req_meta = state.get("req_meta") or {}
    for meta in req_meta.values():
        if not isinstance(meta, dict):
            continue
        if _normalize_profile_budget_key(meta.get("profile")) != profile_key:
            continue
        total += max(0.0, _safe_money(meta.get("stake")))

    seen_meta = set()
    contract_meta = state.get("contract_meta") or {}
    for meta in contract_meta.values():
        if not isinstance(meta, dict):
            continue
        marker = id(meta)
        if marker in seen_meta:
            continue
        seen_meta.add(marker)
        if _normalize_profile_budget_key(meta.get("profile")) != profile_key:
            continue
        total += max(0.0, _safe_money(meta.get("stake")))

    return round(total + 1e-9, 2)


def _resolve_post_contract_balance(state, profit):
    current_balance = _get_effective_state_balance(state)
    last_live_balance = _safe_money(state.get("last_live_balance", 0.0))
    last_known_trade_balance = _safe_money(state.get("last_known_trade_balance", 0.0))
    local_adjustment = _safe_money(state.get("local_balance_adjustment", 0.0))
    profit_value = _safe_money(profit, 0.0)
    last_live_balance_updated_at = _safe_money(state.get("last_live_balance_updated_at", 0.0))
    last_balance_update_at = _safe_money(state.get("balance_updated_at", 0.0))
    live_adjusted_balance = _effective_trade_balance(last_live_balance + local_adjustment) if last_live_balance > 0.0 else 0.0

    now_ts = time.time()
    # If a real Deriv balance update just arrived, trust that live number and
    # do not immediately re-apply the same settled profit again.
    if (
        last_live_balance_updated_at
        and (now_ts - last_live_balance_updated_at) <= 0.75
        and abs(current_balance - _effective_trade_balance(last_live_balance)) <= 0.01
    ):
        state["balance"] = current_balance
        if current_balance > 0.0:
            state["last_known_trade_balance"] = current_balance
        state["balance_updated_at"] = now_ts
        return current_balance

    if (
        not last_live_balance_updated_at
        and not local_adjustment
        and last_balance_update_at
        and (now_ts - last_balance_update_at) <= 0.75
        and (last_live_balance <= 0.0 or abs(current_balance - _effective_trade_balance(last_live_balance)) <= 0.01)
    ):
        state["balance"] = current_balance
        if current_balance > 0.0:
            state["last_known_trade_balance"] = current_balance
        state["balance_updated_at"] = now_ts
        return current_balance

    if last_live_balance > 0.0 and abs(current_balance - live_adjusted_balance) <= 0.01:
        next_adjustment = round(local_adjustment + profit_value, 2)
        next_balance = _effective_trade_balance(last_live_balance + next_adjustment)
        state["local_balance_adjustment"] = next_adjustment
    elif current_balance > 0.0:
        next_balance = _effective_trade_balance(current_balance + profit_value)
        state["local_balance_adjustment"] = 0.0
    elif current_balance <= 0.0 and last_known_trade_balance > 0.0:
        next_balance = _effective_trade_balance(last_known_trade_balance + profit_value)
        state["local_balance_adjustment"] = 0.0
    else:
        next_balance = _effective_trade_balance(current_balance + profit_value)
        state["local_balance_adjustment"] = 0.0

    state["balance"] = next_balance
    if next_balance > 0.0:
        state["last_known_trade_balance"] = next_balance
    state["balance_updated_at"] = now_ts
    return next_balance


# ---------------- DERIV BUY FUNCTION (PER CLIENT) ---------------- #
def _normalize_trade_duration_unit(duration_unit, default="t"):
    unit = str(duration_unit or default).strip().lower()
    if unit not in ("t", "s", "m", "h"):
        unit = default
    return unit


def _sanitize_trade_duration_for_unit(duration, duration_unit, default=1):
    try:
        value = int(float(duration or default))
    except Exception:
        value = int(default or 1)
    unit = _normalize_trade_duration_unit(duration_unit)
    max_duration = 30 if unit == "s" else 20
    return max(1, min(max_duration, value))


def send_buy(client_id, contract_type, stake, symbol, barrier, duration=1, duration_unit="t", mode=None, extra_meta=None, minimum_profit=None, minimum_profit_retries=0, buy_best_available=False):
    state = clients.get(client_id)
    _log_trade_path(client_id, "send_buy_received", state, contract_type=contract_type, symbol=symbol, barrier=barrier)
    ready, ready_msg = _ensure_trade_socket_ready(client_id, state)
    if not ready:
        return False, ready_msg
    ws = state.get("ws")
    symbol = str(symbol or state.get("current_symbol") or "R_10").strip()
    if not symbol:
        return False, "Invalid symbol"

    try:
        stake_value = float(stake)
    except Exception:
        stake_value = 0.0
    balance_value = _get_pre_trade_available_balance(state)
    if balance_value > 0.0:
        state["last_known_trade_balance"] = balance_value
    skip_balance_precheck = _should_skip_local_balance_precheck(state)
    if skip_balance_precheck:
        logger.info(
            "[%s] TEMP trade_path_balance_precheck_skipped reason=oauth_balance_pending stake=%s",
            client_id,
            stake_value,
        )
    if (not skip_balance_precheck) and stake_value > 0 and (_effective_trade_balance(balance_value) + 1e-9) < stake_value:
        logger.warning(
            "[%s] TEMP trade_path_blocked reason=insufficient_local_balance stake=%s balance=%s token_type=%s",
            client_id,
            stake_value,
            balance_value,
            _deriv_connection_type(state),
        )
        try:
            socketio.emit("api_error", {"message": "Insufficient funds to place trade"}, room=client_id)
        except Exception:
            pass
        return False, "Insufficient funds"

    # PATCH D: Block digit trades if profile session is TP/SL blocked
    profile = state.get("active_profile", "KOOLKID")
    strategy = state.get("strategies", {}).get(profile)

    if strategy and hasattr(strategy, "enforce_tp_sl"):
        strategy.enforce_tp_sl()
        if getattr(strategy, "risk_block_reason", None):
            return False, f"{strategy.risk_block_reason} (session limit reached)"

    contract_map = {
        "OVER": "DIGITOVER",
        "UNDER": "DIGITUNDER",
        "MATCHES": "DIGITMATCH",
        "MATCH": "DIGITMATCH",
        "DIFFERS": "DIGITDIFF",
        "DIFFER": "DIGITDIFF",
        "DIFF": "DIGITDIFF",
        "EVEN": "DIGITEVEN",
        "ODD": "DIGITODD",
    }

    normalized_deriv_contract = _normalize_deriv_contract_type(contract_type)
    raw_contract_key = str(contract_type or "").upper().strip()
    if raw_contract_key not in contract_map and normalized_deriv_contract not in _DERIV_DIGIT_CONTRACT_TYPES:
        return False, "Invalid contract type"

    deriv_contract = contract_map.get(raw_contract_key, normalized_deriv_contract)
    barrier = _barrier_from_trade_label(contract_type, barrier)
    duration_unit = _normalize_trade_duration_unit(duration_unit)
    duration = _sanitize_trade_duration_for_unit(duration, duration_unit, default=1)

    budget_ok, budget_msg, budget_reservation = _reserve_profile_budget(state, profile, stake_value)
    if not budget_ok:
        try:
            socketio.emit("api_error", {"message": budget_msg}, room=client_id)
        except Exception:
            pass
        return False, budget_msg

    req_id = _new_req_id()
    state["req_meta"][req_id] = {
        "profile": profile,  # PATCH D: use the same profile variable
        "type": contract_type,
        "barrier": (int(barrier) if barrier not in (None, "") else None),
        "stake": float(stake),
        "symbol": symbol,
        "time": now_time(),
        "mode": mode,
        "duration": duration,
        "duration_unit": duration_unit,
        "deriv_contract_type": deriv_contract,
        "budget_reservation": budget_reservation,
    }
    if isinstance(extra_meta, dict):
        state["req_meta"][req_id].update(extra_meta)
    if minimum_profit not in (None, ""):
        try:
            state["req_meta"][req_id]["minimum_profit"] = float(minimum_profit)
        except Exception:
            pass
    if minimum_profit_retries not in (None, ""):
        try:
            state["req_meta"][req_id]["minimum_profit_retries"] = int(minimum_profit_retries)
        except Exception:
            pass
    _stamp_trade_latency(state["req_meta"][req_id], "buy_send")

    ok, msg = execute_deriv_trade({
        "client_id": client_id,
        "state": state,
        "req_id": req_id,
        "profile": profile,
        "strategy_name": profile,
        "contract_type": deriv_contract,
        "stake": stake,
        "symbol": symbol,
        "barrier": barrier,
        "duration": duration,
        "duration_unit": duration_unit,
        "mode": mode,
        "budget_reservation": budget_reservation,
        "req_meta": state["req_meta"].get(req_id, {}),
        "minimum_profit": minimum_profit,
        "minimum_profit_retries": minimum_profit_retries,
        "buy_best_available": bool(buy_best_available),
    })
    if not ok:
        try:
            _release_profile_budget_reservation(state, budget_reservation)
            _pull_req_meta_by_req_id(state, req_id)
        except Exception:
            pass
        if str(mode or "").upper() == "KIDGX":
            _reset_kidgx_trade_state(client_id, state, profile, meta=state.get("req_meta", {}).get(req_id, {}), reason="trade_send_failed")
    elif str(mode or "").upper() == "KIDGX":
        _mark_kidgx_trade_started(
            client_id,
            state,
            profile,
            meta=state.get("req_meta", {}).get(req_id, {}),
            symbol=symbol,
            contract_type=deriv_contract,
            barrier=barrier,
        )
    return ok, msg


# ==================== PATCH 1C: send_buy_with_profile ====================
def send_buy_with_profile(
    client_id,
    profile,
    contract_type,
    stake,
    symbol,
    barrier,
    duration=1,
    duration_unit="t",
    mode=None,
    skip_local_balance_check=False,
    emit_balance_after_send=True,
    extra_meta=None,
    minimum_profit=None,
    minimum_profit_retries=0,
    buy_best_available=False,
):
    state = clients.get(client_id)
    _log_trade_path(client_id, "send_buy_with_profile_received", state, profile=profile, contract_type=contract_type, symbol=symbol, barrier=barrier)
    ready, ready_msg = _ensure_trade_socket_ready(client_id, state)
    if not ready:
        return False, ready_msg
    ws = state.get("ws")
    symbol = str(symbol or state.get("current_symbol") or "R_10").strip()
    if not symbol:
        return False, "Invalid symbol"

    try:
        stake_value = float(stake)
    except Exception:
        stake_value = 0.0
    balance_value = _get_pre_trade_available_balance(state)
    if balance_value > 0.0:
        state["last_known_trade_balance"] = balance_value
    skip_balance_precheck = _should_skip_local_balance_precheck(state)
    if skip_balance_precheck:
        logger.info(
            "[%s] TEMP trade_path_balance_precheck_skipped reason=oauth_balance_pending profile=%s stake=%s",
            client_id,
            profile,
            stake_value,
        )
    if (
        not bool(skip_local_balance_check)
        and not skip_balance_precheck
        and stake_value > 0
        and (_effective_trade_balance(balance_value) + 1e-9) < stake_value
    ):
        logger.warning(
            "[%s] TEMP trade_path_blocked reason=insufficient_local_balance profile=%s stake=%s balance=%s token_type=%s",
            client_id,
            profile,
            stake_value,
            balance_value,
            _deriv_connection_type(state),
        )
        try:
            socketio.emit("api_error", {"message": "Insufficient funds to place trade"}, room=client_id)
        except Exception:
            pass
        return False, "Insufficient funds"

    # Enforce TP/SL for that profile (if your strategy supports it)
    strat = (state.get("strategies") or {}).get(profile)
    if strat and hasattr(strat, "enforce_tp_sl"):
        try:
            strat.enforce_tp_sl()
            if getattr(strat, "risk_block_reason", None):
                return False, f"{strat.risk_block_reason} (session limit reached)"
        except Exception:
            pass

    contract_map = {
        "OVER": "DIGITOVER",
        "UNDER": "DIGITUNDER",
        "MATCHES": "DIGITMATCH",
        "MATCH": "DIGITMATCH",
        "DIFFERS": "DIGITDIFF",
        "DIFFER": "DIGITDIFF",
        "DIFF": "DIGITDIFF",
        "EVEN": "DIGITEVEN",
        "ODD": "DIGITODD",
    }
    normalized_deriv_contract = _normalize_deriv_contract_type(contract_type)
    raw_contract_key = str(contract_type or "").upper().strip()
    if raw_contract_key not in contract_map and normalized_deriv_contract not in _DERIV_DIGIT_CONTRACT_TYPES:
        return False, "Invalid contract type"

    deriv_contract = contract_map.get(raw_contract_key, normalized_deriv_contract)
    barrier = _barrier_from_trade_label(contract_type, barrier)
    duration_unit = _normalize_trade_duration_unit(duration_unit)
    duration = _sanitize_trade_duration_for_unit(duration, duration_unit, default=1)

    budget_ok, budget_msg, budget_reservation = _reserve_profile_budget(state, profile, stake_value)
    if not budget_ok:
        try:
            socketio.emit("api_error", {"message": budget_msg}, room=client_id)
        except Exception:
            pass
        return False, budget_msg

    req_id = _new_req_id()
    state["req_meta"][req_id] = {
        "profile": profile,
        "type": contract_type,
        "barrier": (int(barrier) if barrier not in (None, "") else None),
        "stake": float(stake),
        "symbol": symbol,
        "time": now_time(),
        "mode": mode,
        "duration": duration,
        "duration_unit": duration_unit,
        "deriv_contract_type": deriv_contract,
        "budget_reservation": budget_reservation,
    }
    if isinstance(extra_meta, dict):
        state["req_meta"][req_id].update(extra_meta)
    if minimum_profit not in (None, ""):
        try:
            state["req_meta"][req_id]["minimum_profit"] = float(minimum_profit)
        except Exception:
            pass
    if minimum_profit_retries not in (None, ""):
        try:
            state["req_meta"][req_id]["minimum_profit_retries"] = int(minimum_profit_retries)
        except Exception:
            pass
    _stamp_trade_latency(state["req_meta"][req_id], "buy_send")

    ok, msg = execute_deriv_trade({
        "client_id": client_id,
        "state": state,
        "req_id": req_id,
        "profile": profile,
        "strategy_name": profile,
        "contract_type": deriv_contract,
        "stake": stake,
        "symbol": symbol,
        "barrier": barrier,
        "duration": duration,
        "duration_unit": duration_unit,
        "mode": mode,
        "budget_reservation": budget_reservation,
        "req_meta": state["req_meta"].get(req_id, {}),
        "minimum_profit": minimum_profit,
        "minimum_profit_retries": minimum_profit_retries,
        "buy_best_available": bool(buy_best_available),
    })
    if not ok:
        try:
            _release_profile_budget_reservation(state, budget_reservation)
            _pull_req_meta_by_req_id(state, req_id)
            if emit_balance_after_send:
                _emit_balance_payload(client_id, state)
        except Exception:
            pass
        if str(mode or "").upper() == "KIDGX":
            _reset_kidgx_trade_state(client_id, state, profile, meta=state.get("req_meta", {}).get(req_id, {}), reason="trade_send_failed")
    elif emit_balance_after_send:
        try:
            _emit_balance_payload(client_id, state)
        except Exception:
            pass
    if ok and str(mode or "").upper() == "KIDGX":
        _mark_kidgx_trade_started(
            client_id,
            state,
            profile,
            meta=state.get("req_meta", {}).get(req_id, {}),
            symbol=symbol,
            contract_type=deriv_contract,
            barrier=barrier,
        )
    return ok, msg


# ---------------- RISE/FALL ORDER (HUMAN Smart Assist) ---------------- #
def place_risefall_order(client_id, signal):
    state = clients.get(client_id)
    ready, ready_msg = _ensure_trade_socket_ready(client_id, state)
    if not ready:
        return False, ready_msg

    strategy = state.get("strategies", {}).get("HUMAN")
    if strategy and hasattr(strategy, "enforce_tp_sl"):
        try:
            strategy.enforce_tp_sl()
            if getattr(strategy, "risk_block_reason", None):
                return False, f"{strategy.risk_block_reason} (session limit reached)"
        except Exception:
            pass

    ws = state.get("ws")

    direction = str(signal.get("direction") or "").upper()
    allow_equals = bool(signal.get("allow_equals", False))
    contract_map = {"RISE": "CALL", "FALL": "PUT"}
    equal_contract_map = {"RISE": "CALLE", "FALL": "PUTE"}
    deriv_contract = (equal_contract_map if allow_equals else contract_map).get(direction)
    if not deriv_contract:
        return False, "Invalid rise/fall direction"

    stake = float(signal.get("stake", state.get("auto_stake", 1.0)))
    duration_unit = _normalize_trade_duration_unit(signal.get("duration_unit", "t"))
    duration = _sanitize_trade_duration_for_unit(signal.get("duration", 5), duration_unit, default=5)
    symbol_to_use = signal.get("symbol") or state.get("human_symbol") or state.get("current_symbol")

    budget_ok, budget_msg, budget_reservation = _reserve_profile_budget(state, "HUMAN", stake)
    if not budget_ok:
        try:
            socketio.emit("api_error", {"message": budget_msg}, room=client_id)
        except Exception:
            pass
        return False, budget_msg

    req_id = _new_req_id()
    state["req_meta"][req_id] = {
        "profile": "HUMAN",
        "type": direction,
        "barrier": None,
        "stake": stake,
        "symbol": symbol_to_use,
        "time": now_time(),
        "mode": signal.get("mode") or "human_rf",
        "duration": duration,
        "duration_unit": duration_unit,
        "allow_equals": allow_equals,
        "contract_type": deriv_contract,
        "budget_reservation": budget_reservation,
    }
    if isinstance(signal.get("extra_meta"), dict):
        state["req_meta"][req_id].update(signal.get("extra_meta"))
    _stamp_trade_latency(state["req_meta"][req_id], "buy_send")

    payload = {
        "req_id": req_id,
        "buy": 1,
        "price": float(stake),
        "parameters": {
            "amount": float(stake),
            "basis": "stake",
            "contract_type": deriv_contract,
            "currency": "USD",
            "duration": duration,
            "duration_unit": duration_unit,
            "symbol": symbol_to_use,
        }
    }

    try:
        _log_trade_path(client_id, "buy_about_to_be_sent", state, req_id=req_id, contract=deriv_contract, symbol=symbol_to_use)
        ok, msg = _send_trade_payload_with_oauth_proposal(client_id, state, req_id, payload, stake)
        if not ok:
            try:
                _release_profile_budget_reservation(state, budget_reservation)
            except Exception:
                pass
            return False, msg
        _emit_balance_payload(client_id, state)
        return True, msg
    except Exception as e:
        _mark_ws_unhealthy_and_reconnect(client_id, state, "Deriv connection failed while sending a trade. Reconnecting now...")
        try:
            _pull_req_meta_by_req_id(state, req_id)
        except Exception:
            pass
        try:
            _release_profile_budget_reservation(state, budget_reservation)
            _emit_balance_payload(client_id, state)
        except Exception:
            pass
        return False, str(e)


def _fetch_human_manual_contracts_for_symbol(symbol, *, force_refresh=False):
    return _module_fetch_human_manual_contracts_for_symbol(
        symbol,
        deriv_ws_url=DERIV_WS,
        force_refresh=force_refresh,
    )


def _fetch_human_manual_contracts_for_state(state, *, force_refresh=False):
    return _module_fetch_human_manual_contracts_for_state(
        state,
        deriv_ws_url=DERIV_WS,
        force_refresh=force_refresh,
    )


def _request_human_manual_proposal_quote(
    state,
    *,
    contract_type,
    stake,
    symbol,
    duration,
    duration_unit="t",
    selected_tick=None,
    timeout_sec=5.0,
):
    client_id = None
    for _cid, _state in clients.items():
        if _state is state:
            client_id = _cid
            break
    if client_id is not None:
        ready, ready_msg = _ensure_trade_socket_ready(client_id, state, emit_error=False)
        if not ready:
            return None, ready_msg
    ws = state.get("ws")
    rate_limit_msg = _proposal_rate_limit_wait_message(state)
    if rate_limit_msg:
        return None, rate_limit_msg
    if not ws:
        return None, "Not connected"

    try:
        amount = float(stake)
    except Exception:
        return None, "Invalid stake"
    if amount <= 0:
        return None, "Stake must be greater than 0"

    try:
        duration_val = int(float(duration))
    except Exception:
        return None, "Invalid duration"
    duration_val = max(1, duration_val)
    unit = str(duration_unit or "t").strip().lower()
    if unit not in ("t", "s", "m", "h", "d"):
        unit = "t"

    req_id = _new_req_id()
    waiter = {"event": threading.Event(), "proposal": None, "error": None}
    waiters = state.setdefault("_proposal_waiters", {})
    waiters[req_id] = waiter
    waiters[str(req_id)] = waiter

    payload = {
        "proposal": 1,
        "amount": float(amount),
        "basis": "stake",
        "contract_type": str(contract_type or "").upper().strip(),
        "currency": "USD",
        "duration": int(duration_val),
        "duration_unit": unit,
        "symbol": symbol,
        "req_id": req_id,
    }
    if selected_tick is not None:
        payload["selected_tick"] = int(selected_tick)
    payload = _proposal_payload_for_connection(state, payload)

    try:
        if client_id is not None:
            logger.info(
                "[%s] TEMP proposal_about_to_be_sent token_type=%s payload=%s",
                client_id,
                _deriv_connection_type(state),
                _safe_deriv_payload_text(payload),
            )
        ws.send(json.dumps(payload))
        if client_id is not None:
            logger.info("[%s] TEMP proposal_actually_sent req_id=%s token_type=%s", client_id, req_id, _deriv_connection_type(state))
    except Exception as e:
        if client_id is not None and _should_force_ws_reconnect_on_send_exception(state, e):
            _mark_ws_unhealthy_and_reconnect(client_id, state, "Deriv connection failed while requesting a quote. Reconnecting now...", emit_error=False)
        waiters.pop(req_id, None)
        waiters.pop(str(req_id), None)
        return None, str(e)

    if not waiter["event"].wait(max(0.40, float(timeout_sec))):
        waiters.pop(req_id, None)
        waiters.pop(str(req_id), None)
        return None, "Quote timeout"

    waiters.pop(req_id, None)
    waiters.pop(str(req_id), None)
    if waiter.get("error"):
        err_payload = waiter.get("error")
        _mark_proposal_rate_limited(state, err_payload)
        return None, _friendly_proposal_error_message(err_payload)

    proposal = waiter.get("proposal") or {}
    proposal_id = proposal.get("id")
    if proposal_id in (None, ""):
        return None, "Proposal id missing"
    ask_price = _safe_float(proposal.get("ask_price"), _safe_float(proposal.get("display_value"), amount))
    return {
        "id": proposal_id,
        "ask_price": float(max(0.0, ask_price if ask_price is not None else amount)),
        "contract_type": str(contract_type or "").upper().strip(),
        "duration": int(duration_val),
        "duration_unit": unit,
        "symbol": symbol,
        "selected_tick": selected_tick,
    }, None


def place_human_manual_contract(
    client_id,
    *,
    action,
    stake,
    selected_tick=None,
    duration_ticks=None,
    symbol=None,
    mode="human_manual_contract",
    extra_meta=None,
):
    state = clients.get(client_id)
    ready, ready_msg = _ensure_trade_socket_ready(client_id, state)
    if not ready:
        return False, ready_msg, None

    action_key = normalize_human_manual_action(action)
    if not action_key:
        return False, "Invalid HUMAN manual action", None

    try:
        stake_value = max(0.35, float(stake))
    except Exception:
        return False, "Invalid stake", None

    strategy = state.get("strategies", {}).get("HUMAN")
    if strategy and hasattr(strategy, "enforce_tp_sl"):
        try:
            strategy.enforce_tp_sl()
            if getattr(strategy, "risk_block_reason", None):
                return False, f"{strategy.risk_block_reason} (session limit reached)", None
        except Exception:
            pass

    requested_symbol = str(symbol or "").strip()
    if requested_symbol:
        info, err, resolved_symbol = _fetch_human_manual_contracts_for_symbol(requested_symbol)
        symbol = resolved_symbol or requested_symbol
    else:
        info, err, symbol = _fetch_human_manual_contracts_for_state(state)
    if err:
        return False, err, None
    action_info = (info or {}).get(action_key) or {}
    if not action_info.get("available") or not action_info.get("contract_type"):
        return False, "This contract is not available for the selected market.", None

    duration_unit = str(action_info.get("duration_unit") or "t").lower()
    min_duration = int(action_info.get("min_duration") or 1)
    max_duration = action_info.get("max_duration")
    if action_key in ("HIGH_TICK", "LOW_TICK"):
        try:
            selected_tick_value = int(float(selected_tick))
        except Exception:
            return False, "Selected Tick must be an integer from 1 to 5", None
        if selected_tick_value < 1 or selected_tick_value > 5:
            return False, "Selected Tick must be an integer from 1 to 5", None
        duration_value = max(min_duration, int(action_info.get("default_duration") or 5), 5)
        if max_duration is not None:
            duration_value = min(duration_value, int(max_duration))
        selected_tick_for_proposal = selected_tick_value
    else:
        try:
            duration_value = int(float(duration_ticks))
        except Exception:
            return False, "Tick duration must be a valid integer", None
        if duration_value < min_duration:
            return False, f"Tick duration must be at least {min_duration}", None
        if max_duration is not None and duration_value > int(max_duration):
            return False, f"Tick duration must be {int(max_duration)} or less", None
        selected_tick_for_proposal = None

    quote, quote_err = _request_human_manual_proposal_quote(
        state,
        contract_type=action_info.get("contract_type"),
        stake=stake_value,
        symbol=symbol,
        duration=duration_value,
        duration_unit=duration_unit,
        selected_tick=selected_tick_for_proposal,
        timeout_sec=5.0,
    )
    if quote_err:
        return False, quote_err, None

    budget_ok, budget_msg, budget_reservation = _reserve_profile_budget(state, "HUMAN", stake_value)
    if not budget_ok:
        try:
            socketio.emit("api_error", {"message": budget_msg}, room=client_id)
        except Exception:
            pass
        return False, budget_msg, None

    req_id = _new_req_id()
    label = str(action_info.get("label") or action_key.replace("_", " ")).upper()
    state.setdefault("req_meta", {})[req_id] = {
        "profile": "HUMAN",
        "type": label,
        "barrier": selected_tick_for_proposal,
        "stake": stake_value,
        "symbol": symbol,
        "time": now_time(),
        "mode": mode or "human_manual_contract",
        "duration": int(duration_value),
        "duration_unit": duration_unit,
        "contract_type": action_info.get("contract_type"),
        "selected_tick": selected_tick_for_proposal,
        "budget_reservation": budget_reservation,
    }
    if isinstance(extra_meta, dict):
        state["req_meta"][req_id].update(extra_meta)
    _stamp_trade_latency(state["req_meta"][req_id], "buy_send")

    payload = {
        "req_id": req_id,
        "buy": quote.get("id"),
        "price": float(quote.get("ask_price") or stake_value),
    }
    try:
        _log_trade_path(client_id, "buy_about_to_be_sent", state, req_id=req_id, action=action_key, symbol=symbol)
        logger.info("[%s] TEMP buy_about_to_be_sent token_type=%s payload=%s", client_id, _deriv_connection_type(state), _safe_deriv_payload_text(payload))
        state["ws"].send(json.dumps(payload))
        logger.info("[%s] TEMP buy_actually_sent req_id=%s token_type=%s", client_id, req_id, _deriv_connection_type(state))
        _emit_balance_payload(client_id, state)
        return True, "Trade sent", {
            "action": action_key,
            "label": action_info.get("label"),
            "contract_type": action_info.get("contract_type"),
            "symbol": symbol,
            "duration": duration_value,
            "duration_unit": duration_unit,
            "selected_tick": selected_tick_for_proposal,
        }
    except Exception as e:
        _mark_ws_unhealthy_and_reconnect(client_id, state, "Deriv connection failed while sending a trade. Reconnecting now...")
        try:
            _pull_req_meta_by_req_id(state, req_id)
            _release_profile_budget_reservation(state, budget_reservation)
            _emit_balance_payload(client_id, state)
        except Exception:
            pass
        return False, str(e), None


def place_human_manual_contract_batch(client_id, *, actions):
    state = clients.get(client_id)
    ready, ready_msg = _ensure_trade_socket_ready(client_id, state)
    if not ready:
        return False, ready_msg, []
    if not isinstance(actions, list) or len(actions) < 2:
        return False, "At least two HUMAN manual actions are required.", []

    strategy = state.get("strategies", {}).get("HUMAN")
    if strategy and hasattr(strategy, "enforce_tp_sl"):
        try:
            strategy.enforce_tp_sl()
            if getattr(strategy, "risk_block_reason", None):
                return False, f"{strategy.risk_block_reason} (session limit reached)", []
        except Exception:
            pass

    info, err, symbol = _fetch_human_manual_contracts_for_state(state)
    if err:
        return False, err, []

    prepared = []
    reservations = []
    req_ids = []
    pair_batch_id = _new_req_id()
    send_phase = False
    try:
        for index, item in enumerate(actions):
            item = item or {}
            action_key = normalize_human_manual_action(item.get("action"))
            if not action_key:
                raise ValueError("Invalid HUMAN manual action")

            try:
                stake_value = max(0.35, float(item.get("stake")))
            except Exception:
                raise ValueError("Invalid stake")

            action_info = (info or {}).get(action_key) or {}
            if not action_info.get("available") or not action_info.get("contract_type"):
                raise ValueError("This contract is not available for the selected market.")

            duration_unit = str(action_info.get("duration_unit") or "t").lower()
            min_duration = int(action_info.get("min_duration") or 1)
            max_duration = action_info.get("max_duration")
            if action_key in ("HIGH_TICK", "LOW_TICK"):
                try:
                    selected_tick_value = int(float(item.get("selected_tick")))
                except Exception:
                    raise ValueError("Selected Tick must be an integer from 1 to 5")
                if selected_tick_value < 1 or selected_tick_value > 5:
                    raise ValueError("Selected Tick must be an integer from 1 to 5")
                duration_value = max(min_duration, int(action_info.get("default_duration") or 5), 5)
                if max_duration is not None:
                    duration_value = min(duration_value, int(max_duration))
                selected_tick_for_proposal = selected_tick_value
            else:
                try:
                    duration_value = int(float(item.get("duration_ticks")))
                except Exception:
                    raise ValueError("Tick duration must be a valid integer")
                if duration_value < min_duration:
                    raise ValueError(f"Tick duration must be at least {min_duration}")
                if max_duration is not None and duration_value > int(max_duration):
                    raise ValueError(f"Tick duration must be {int(max_duration)} or less")
                selected_tick_for_proposal = None

            quote, quote_err = _request_human_manual_proposal_quote(
                state,
                contract_type=action_info.get("contract_type"),
                stake=stake_value,
                symbol=symbol,
                duration=duration_value,
                duration_unit=duration_unit,
                selected_tick=selected_tick_for_proposal,
                timeout_sec=5.0,
            )
            if quote_err:
                raise ValueError(str(quote_err))

            budget_ok, budget_msg, budget_reservation = _reserve_profile_budget(state, "HUMAN", stake_value)
            if not budget_ok:
                try:
                    socketio.emit("api_error", {"message": budget_msg}, room=client_id)
                except Exception:
                    pass
                raise ValueError(str(budget_msg))

            req_id = _new_req_id()
            label = str(action_info.get("label") or action_key.replace("_", " ")).upper()
            state.setdefault("req_meta", {})[req_id] = {
                "profile": "HUMAN",
                "type": label,
                "barrier": selected_tick_for_proposal,
                "stake": stake_value,
                "symbol": symbol,
                "time": now_time(),
                "mode": "human_manual_contract",
                "duration": int(duration_value),
                "duration_unit": duration_unit,
                "contract_type": action_info.get("contract_type"),
                "selected_tick": selected_tick_for_proposal,
                "budget_reservation": budget_reservation,
                "pair_batch_id": pair_batch_id,
                "pair_batch_size": len(actions),
                "pair_leg_index": index,
                "pair_action": action_key,
                "pair_retry_count": 0,
            }
            _stamp_trade_latency(state["req_meta"][req_id], "buy_send")
            req_ids.append(req_id)
            reservations.append(budget_reservation)
            prepared.append({
                "req_id": req_id,
                "price": float(quote.get("ask_price") or stake_value),
                "buy": quote.get("id"),
                "trade": {
                    "action": action_key,
                    "label": action_info.get("label"),
                    "contract_type": action_info.get("contract_type"),
                    "symbol": symbol,
                    "duration": duration_value,
                    "duration_unit": duration_unit,
                    "selected_tick": selected_tick_for_proposal,
                },
            })

        lock = _get_ws_lifecycle_lock(state)
        with lock:
            send_phase = True
            ws = state.get("ws")
            if not state.get("ws_connected") or not ws:
                raise ValueError("Not connected")
            for index, item in enumerate(prepared):
                ws.send(json.dumps({
                    "req_id": item["req_id"],
                    "buy": item["buy"],
                    "price": item["price"],
                }))
                logger.info(
                    "[%s] human_manual_pair_send leg=%s/%s action=%s",
                    client_id,
                    index + 1,
                    len(prepared),
                    item["trade"].get("action"),
                )
                if index < (len(prepared) - 1):
                    delay_sec = max(0.0, float(HUMAN_PAIR_BATCH_SEND_DELAY_SEC))
                    if delay_sec > 0:
                        time.sleep(delay_sec)
        _emit_balance_payload(client_id, state)
        return True, f"Sent {len(prepared)} HUMAN manual trades", [item["trade"] for item in prepared]
    except Exception as e:
        if send_phase:
            try:
                should_reconnect = _should_force_ws_reconnect_on_send_exception(state, e)
                logger.warning(
                    "[%s] human_manual_pair_send_failed reconnect=%s error=%s",
                    client_id,
                    should_reconnect,
                    e,
                )
                if state and should_reconnect:
                    _mark_ws_unhealthy_and_reconnect(client_id, state, "Deriv connection failed while sending HUMAN pair trades. Reconnecting now...", emit_error=False)
            except Exception:
                pass
        for req_id in req_ids:
            try:
                _pull_req_meta_by_req_id(state, req_id)
            except Exception:
                pass
        for reservation in reservations:
            try:
                _release_profile_budget_reservation(state, reservation)
            except Exception:
                pass
        try:
            _emit_balance_payload(client_id, state)
        except Exception:
            pass
        return False, str(e), [item.get("trade") for item in prepared if isinstance(item, dict)]


def _retry_human_manual_pair_leg_after_error(client_id, state, meta, error_message):
    if not isinstance(meta, dict) or not isinstance(state, dict):
        return False, None
    if str(meta.get("profile") or "").upper() != "HUMAN":
        return False, None
    pair_batch_id = meta.get("pair_batch_id")
    if pair_batch_id in (None, ""):
        return False, None
    try:
        pair_size = int(meta.get("pair_batch_size") or 0)
    except Exception:
        pair_size = 0
    if pair_size < 2:
        return False, None
    try:
        retry_count = int(meta.get("pair_retry_count") or 0)
    except Exception:
        retry_count = 0
    if retry_count >= 1:
        return False, None

    ready, ready_msg = _ensure_trade_socket_ready(client_id, state, emit_error=False)
    if not ready:
        return False, ready_msg

    stake = _safe_float(meta.get("stake"), None)
    if stake is None or stake <= 0:
        return False, "Invalid retry stake"

    quote, quote_err = _request_human_manual_proposal_quote(
        state,
        contract_type=meta.get("contract_type"),
        stake=stake,
        symbol=meta.get("symbol"),
        duration=meta.get("duration"),
        duration_unit=meta.get("duration_unit") or "t",
        selected_tick=meta.get("selected_tick"),
        timeout_sec=5.0,
    )
    if quote_err:
        return False, str(quote_err)

    budget_ok, budget_msg, budget_reservation = _reserve_profile_budget(state, "HUMAN", stake)
    if not budget_ok:
        return False, str(budget_msg)

    new_req_id = _new_req_id()
    retry_meta = dict(meta)
    retry_meta["time"] = now_time()
    retry_meta["budget_reservation"] = budget_reservation
    retry_meta["pair_retry_count"] = retry_count + 1
    retry_meta["retry_of_req_id"] = meta.get("req_id")
    retry_meta["last_buy_error"] = str(error_message or "")
    state.setdefault("req_meta", {})[new_req_id] = retry_meta
    _stamp_trade_latency(state["req_meta"][new_req_id], "buy_send")
    try:
        state["ws"].send(json.dumps({
            "req_id": new_req_id,
            "buy": quote.get("id"),
            "price": float(quote.get("ask_price") or stake),
        }))
        logger.info(
            "[%s] human_manual_pair_leg_retried batch_id=%s action=%s retry_count=%s",
            client_id,
            pair_batch_id,
            meta.get("pair_action") or meta.get("type"),
            retry_meta["pair_retry_count"],
        )
        _emit_balance_payload(client_id, state)
        return True, None
    except Exception as exc:
        state.get("req_meta", {}).pop(new_req_id, None)
        try:
            _release_profile_budget_reservation(state, budget_reservation)
        except Exception:
            pass
        try:
            _emit_balance_payload(client_id, state)
        except Exception:
            pass
        if _should_force_ws_reconnect_on_send_exception(state, exc):
            _mark_ws_unhealthy_and_reconnect(
                client_id,
                state,
                "Deriv connection failed while retrying a HUMAN pair trade. Reconnecting now...",
                emit_error=False,
            )
        return False, str(exc)


def _execute_auto_session_plan(client_id, state, plan):
    if not isinstance(plan, dict):
        return

    for action in list(plan.get("actions") or []):
        try:
            kind = str(action.get("kind") or "").lower().strip()
            if kind == "human_rf":
                signal = {
                    "direction": action.get("direction"),
                    "stake": action.get("stake"),
                    "duration": action.get("duration", 5),
                    "duration_unit": action.get("duration_unit", "t"),
                    "symbol": action.get("symbol"),
                    "mode": action.get("mode"),
                }
                ok, msg = place_risefall_order(client_id, signal)
            elif kind == "unchain_hl":
                ok, msg = _send_unchain_hl_trade(
                    client_id,
                    side=action.get("side"),
                    stake=action.get("stake"),
                    symbol=action.get("symbol"),
                    barrier=action.get("barrier"),
                    duration=action.get("duration", 5),
                    duration_unit=action.get("duration_unit", "t"),
                    entry_source="AUTO_SESSION",
                    auto_confidence=plan.get("confidence"),
                    mode=action.get("mode"),
                )
            else:
                ok, msg = send_buy_with_profile(
                    client_id,
                    action.get("profile"),
                    action.get("contract_type"),
                    action.get("stake"),
                    action.get("symbol"),
                    action.get("barrier"),
                    duration=action.get("duration", 1),
                    duration_unit=action.get("duration_unit", "t"),
                    mode=action.get("mode"),
                )
            if not ok:
                handle_auto_session_buy_failed(state, action, msg)
        except Exception as exc:
            handle_auto_session_buy_failed(state, action, str(exc))


