@app.route("/deriv/oauth/select-account", methods=["POST"])
def deriv_oauth_select_account():
    if not login_required():
        return redirect(url_for("login"))
    cid, state = get_client_state()
    access_token = str(state.get("oauth_pending_access_token") or "").strip()
    accounts = state.get("oauth_pending_accounts") or []
    selected = str(request.form.get("account_id") or "").strip()
    allowed = {str(account.get("account_id") or "") for account in accounts if isinstance(account, dict)}
    if not access_token or not selected or selected not in allowed:
        return "Deriv account selection expired. Please login with Deriv again.", 400
    selected_account = next((account for account in accounts if isinstance(account, dict) and str(account.get("account_id") or "") == selected), {})
    logger.info(
        "[%s] deriv_oauth_account_selected account_id=%s account_kind=%s currency=%s",
        cid,
        _mask_account_id(selected),
        _oauth_account_label(selected_account),
        (selected_account or {}).get("currency") or "",
    )
    state["oauth_pending_access_token"] = ""
    state["oauth_pending_accounts"] = []
    _start_deriv_connection_for_state(cid, state, access_token, "oauth", selected, "deriv_oauth_select", DERIV_OAUTH_APP_ID)
    return redirect(url_for("index"))


@app.route("/set_token", methods=["POST"])
def set_token():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    cid, state = get_client_state()
    data = request.get_json(silent=True) or {}
    token = str(data.get("token", "") or "").strip()
    account_id = str(DERIV_ACCOUNT_ID or "").strip()
    app_id = str(DERIV_APP_ID or "1089").strip() or "1089"
    token_type = "legacy"
    logger.info("[%s] TEMP connect_request_received token_present=%s token_type=%s token=%s", cid, bool(token), token_type, _mask_api_token(token))
    logger.info(
        "[%s] TEMP set_token_runtime server_instance_id=%s process_id=%s runtime_present=%s ws_connected=%s ws_thread_alive=%s",
        cid,
        SERVER_INSTANCE_ID,
        os.getpid(),
        not bool((state.get("last_runtime_diag") or {}).get("client_runtime_missing_before_init")),
        bool(state.get("ws_connected")),
        bool(state.get("ws_thread") and state["ws_thread"].is_alive()),
    )
    if not token:
        logger.warning("[%s] TEMP connect_error_emitted message=missing_token", cid)
        return jsonify({"status": "error", "message": "API token is required"}), 400

    same_token = token == str(state.get("api_token", "") or "").strip()
    same_account_id = account_id == str(state.get("deriv_account_id") or DERIV_ACCOUNT_ID or "").strip()
    same_app_id = app_id == str(state.get("deriv_app_id") or DERIV_APP_ID or "1089").strip()
    ws_thread_alive = bool(state.get("ws_thread") and state["ws_thread"].is_alive())
    same_token_authorized = bool(same_token and same_account_id and same_app_id and state.get("ws_connected") and state.get("ws"))
    same_token_in_progress = bool(
        same_token
        and same_account_id
        and same_app_id
        and not state.get("ws_connected")
        and (
            state.get("ws_transport_connected")
            or state.get("ws_connect_started_at")
            or ws_thread_alive
        )
    )
    connecting_or_authorized = same_token_authorized or same_token_in_progress
    if connecting_or_authorized:
        logger.info(
            "[%s] TEMP set_token_reused_existing_connection ws_connected=%s transport=%s thread_alive=%s",
            cid,
            bool(state.get("ws_connected")),
            bool(state.get("ws_transport_connected")),
            ws_thread_alive,
        )
        return jsonify({
            "status": "connected" if state.get("ws_connected") else "connecting",
            "message": "Connection already in progress",
        })

    state["api_token"] = token
    state["api_token_type"] = token_type
    state["deriv_account_id"] = account_id
    state["options_account_id"] = ""
    state["oauth_options_account_id"] = ""
    state["deriv_app_id"] = app_id
    state["pat_otp_ws_url"] = ""
    state["pat_otp_reconnect_used"] = False
    state["loginid"] = "UNKNOWN"
    state["session_start_balance"] = None
    state["ws_connected"] = False
    state["ws_transport_connected"] = False
    state["ws_last_message_at"] = 0.0
    state["ws_last_authorized_at"] = 0.0
    state["ws_connect_started_at"] = 0.0
    state["ws_authorize_deadline_at"] = 0.0
    state["ws_reconnect_pending"] = False
    state["ws_reconnect_attempts"] = 0
    state["cloud_session_key"] = _cloud_identity_for_state(state).get("key", "")

    # start WS but avoid "2 instances" per browser session
    t = state.get("ws_thread")
    if t and t.is_alive():
        logger.info("[%s] TEMP old_session_socket_cleared alive_thread=True", cid)
        try:
            state["ws_stop_event"].set()
        except Exception:
            pass
        try:
            if state.get("ws"):
                state["ws"].close()
        except Exception:
            pass
    else:
        logger.info("[%s] TEMP old_session_socket_cleared alive_thread=False", cid)

    _start_ws_worker_thread(cid, state, reason="set_token")
    logger.info("[%s] TEMP deriv_websocket_thread_started_from_connect", cid)
    try:
        cloud_key = state.get("cloud_session_key")
        if cloud_key and cloud_manager.has_session(cloud_key):
            status = cloud_manager.status(cloud_key)
            if status.get("running"):
                _ensure_cloud_runtime_for_state(state, cloud_key, status)
    except Exception:
        logger.exception("[%s] cloud_runtime_attach_after_set_token_failed", cid)

    return jsonify({"status": "connecting", "token_type": token_type})


@app.route("/api_connection_status", methods=["GET"])
def api_connection_status():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    _cid, state = get_client_state()
    runtime_diag = _runtime_diag_payload(
        _cid,
        state,
        runtime_missing_before_init=bool((state.get("last_runtime_diag") or {}).get("client_runtime_missing_before_init")),
    )
    _check_ws_connect_timeout(_cid, state)
    warmup_active = _has_active_tick_stream_warmup(state, now_ts=time.time(), client_id=_cid)
    authorized = bool(state.get("ws_connected")) and bool(state.get("ws"))
    connected = authorized
    ws_stale = bool(authorized and not warmup_active and _is_ws_stale(state))
    if ws_stale:
        logger.warning("[%s] api_connection_status_ws_stale action=keep_authorized_self_heal_ticks", _cid)
        try:
            _restore_required_tick_subscriptions(_cid, state, "api_status_stale_self_heal")
        except Exception:
            pass
    tick_health = _get_tick_stream_health(_cid, state, self_heal=connected, allow_reconnect=False)
    has_token = bool(str(state.get("api_token", "") or "").strip())
    reconnecting = bool(
        has_token
        and not connected
        and (
            state.get("ws_reconnect_pending")
            or state.get("ws_connect_started_at")
            or state.get("ws_transport_connected")
        )
    )
    payload = {
        "connected": connected,
        "reconnecting": reconnecting,
        "ws_stale": ws_stale,
        "loginid": state.get("loginid", "UNKNOWN"),
        "has_token": has_token,
        "license_context": get_user_license_context(),
        **runtime_diag,
        **tick_health,
        **_build_balance_payload(state),
    }
    budget = payload.get("active_profile_budget") or {}
    now_ts = time.time()
    last_api_status_log = float(state.get("_api_status_log_at", 0.0) or 0.0)
    if (now_ts - last_api_status_log) >= 30.0:
        state["_api_status_log_at"] = now_ts
        logger.info(
            "[%s] TEMP api_connection_status_runtime server_instance_id=%s runtime_present=%s ws_connected=%s ws_thread_alive=%s reconnecting=%s tick_healthy=%s tick_recovering=%s",
            _cid,
            payload.get("server_instance_id"),
            payload.get("client_runtime_present"),
            payload.get("ws_connected_runtime"),
            payload.get("ws_thread_alive"),
            reconnecting,
            payload.get("tick_stream_healthy"),
            payload.get("tick_stream_recovering"),
        )
        logger.info(
            "[%s] TEMP reconnect_restore_values connected=%s live_account=%s display=%s budget_remaining=%s session_pnl=%s",
            _cid,
            connected,
            payload.get("account_balance"),
            payload.get("display_balance"),
            budget.get("remaining_budget"),
            budget.get("realized_pnl"),
        )
    return jsonify(payload)


@app.route("/koolkid/over3-under6-availability", methods=["POST"])
def koolkid_over3_under6_availability_route():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    cid, state = get_client_state()
    ready, ready_msg = _ensure_trade_socket_ready(cid, state, emit_error=False)
    if not ready:
        return jsonify({"status": "error", "message": ready_msg}), 409

    data = request.get_json(silent=True) or {}
    requested_symbol = str(data.get("symbol") or state.get("current_symbol") or "R_10").strip()
    underlying_symbol, symbol_err = _resolve_deriv_underlying_symbol(cid, state, requested_symbol)
    if symbol_err:
        return jsonify({"status": "error", "message": symbol_err, "symbol": requested_symbol}), 400

    contracts_for, contracts_err = _get_contracts_for_symbol(cid, state, underlying_symbol)
    if contracts_err:
        return jsonify({
            "status": "error",
            "message": contracts_err,
            "symbol": requested_symbol,
            "underlying_symbol": underlying_symbol,
        }), 400

    over_ok = _contracts_for_has_contract_type(contracts_for, "DIGITOVER")
    under_ok = _contracts_for_has_contract_type(contracts_for, "DIGITUNDER")
    if not (over_ok and under_ok):
        return jsonify({
            "status": "error",
            "message": "Over/Under digit contracts are not available on this market.",
            "symbol": requested_symbol,
            "underlying_symbol": underlying_symbol,
            "over_available": bool(over_ok),
            "under_available": bool(under_ok),
        }), 400

    return jsonify({
        "status": "success",
        "symbol": requested_symbol,
        "underlying_symbol": underlying_symbol,
        "over_available": True,
        "under_available": True,
    })


@app.route("/profile_budget", methods=["POST"])
def profile_budget_route():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    cid, state = get_client_state()
    data = request.get_json(silent=True) or {}
    profile = _normalize_profile_budget_key(data.get("profile") or state.get("active_profile"))
    raw_budget = data.get("budget")
    if isinstance(raw_budget, str):
        raw_budget = raw_budget.strip()

    if raw_budget in (None, ""):
        budget_amount = 0.0
    else:
        try:
            budget_amount = max(0.0, float(raw_budget))
        except Exception:
            return jsonify({"status": "error", "message": "Enter a valid budget amount"}), 400

    entry = _ensure_profile_budget(state, profile)
    if budget_amount <= 0:
        entry["amount"] = 0.0
        entry["realized_pnl"] = 0.0
        entry["reserved"] = 0.0
        message = f"{profile} budget cleared"
    else:
        entry["amount"] = round(budget_amount, 2)
        entry["realized_pnl"] = 0.0
        entry["reserved"] = _estimate_profile_open_budget_exposure(state, profile)
        message = f"{profile} budget set to {_format_state_money(state, entry['amount'])}"
    logger.info(
        "[%s] TEMP session_budget_set profile=%s configured=%s remaining=%s realized_pnl=%s live_account=%s",
        cid,
        profile,
        entry.get("amount"),
        _profile_budget_snapshot(state, profile).get("remaining_budget"),
        entry.get("realized_pnl"),
        _get_live_account_balance(state),
    )

    payload = {
        "status": "success",
        "message": message,
        **_build_balance_payload(state, state.get("active_profile")),
    }
    if state.get("active_profile") == profile:
        _emit_balance_payload(cid, state)
        send_stats_update(cid)
    return jsonify(payload)


@app.route("/set_auto_stake", methods=["POST"])
def set_auto_stake():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    cid, state = get_client_state()

    try:
        stake = float((request.json or {}).get("stake", 1))
        if stake <= 0:
            stake = 1.0
    except Exception:
        stake = 1.0

    state["auto_stake"] = stake
    logger.info(f"[{cid}] 💰 AUTO STAKE UPDATED: {stake}")

    # ✅ also sync stake into HUMAN strategy so manual/Rise-Fall uses your stake input
    try:
        h = state["strategies"].get("HUMAN")
        if h and hasattr(h, "stake"):
            h.stake = float(stake)
    except Exception:
        pass

    return jsonify({"status": "success", "auto_stake": stake})


