@app.route("/clear_profile_history", methods=["POST"])
def clear_profile_history():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    cid, state = get_client_state()
    data = request.json or {}
    profile = (data.get("profile") or state.get("active_profile") or "KOOLKID").upper()

    strat = state["strategies"].get(profile)
    if strat and hasattr(strat, "clear_history"):
        strat.clear_history()

    if profile == "UNCHAIN":
        u = _ensure_unchain_hl_state(state)
        u["stats"] = {"wins": 0, "losses": 0, "net_pnl": 0.0}
        u["last_result"] = None
        u["last_action"] = "Ready"
        u["risk_block_reason"] = None
        u["active_contracts"] = {}
        u["auto_pair_active"] = False
        u["auto_next_fire_at"] = 0.0
        u["auto_last_cycle_closed_at"] = 0.0
        u["auto_wait_for_reset"] = False
        u["auto_reset_drop_seen"] = False
        u["auto_cycle_id"] = 0
        u["auto_cycle_settled"] = 0
        u["auto_cycle_losses"] = 0
        u["auto_last_cycle_had_loss"] = False
        u["auto_both_pair_active"] = False
        u["auto_both_next_fire_at"] = 0.0
        u["auto_both_last_cycle_closed_at"] = 0.0
        u["koolkid_hl_simulation"] = None
        u["koolkid_both_simulation"] = None
        u["pair_failure_toast_at"] = 0.0
        u["pair_failure_toast_message"] = ""

    if profile == "NTT":
        ntt = _ensure_ntt_state(state)
        ntt["last_result"] = None
        ntt["last_action"] = "Ready"
        ntt["risk_block_reason"] = None
        ntt["active_contracts"] = {}
        ntt["koolkid_hl_simulation"] = None
        ntt["koolkid_both_simulation"] = None
        state["_processed_ntt_contracts"] = set()

    if profile == "CLOUD":
        cloud_key = _cloud_key_for_state(state)
        if cloud_key:
            cloud_manager.stop(cloud_key, "Stopped")
            cloud_manager.clear_history(cloud_key)
            _stop_cloud_runtime_for_key(cloud_key, "clear_profile_history")

    if profile == state.get("active_profile"):
        send_stats_update(cid)
        if profile == "UNCHAIN":
            socketio.emit("unchain_status", _unchain_payload_response(state), room=cid)
        if profile == "NTT":
            socketio.emit("ntt_status", _ntt_payload_response(state), room=cid)
        if profile == "CLOUD":
            cloud_key = _cloud_key_for_state(state)
            if cloud_key:
                socketio.emit("cloud_under9_status", cloud_manager.status(cloud_key), room=cid)

    payload = None
    if profile == "UNCHAIN":
        payload = _unchain_payload_response(state)
    elif profile == "NTT":
        payload = _ntt_payload_response(state)
    return jsonify({"status": "cleared", "profile": profile, "payload": payload})


@app.route("/set_profile", methods=["POST"])
def set_profile():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    cid, state = get_client_state()
    profile = (request.json or {}).get("profile", "KOOLKID")
    mutant_access = _mutant_access_state()

    if profile not in state["strategies"]:
        return jsonify({"error": "Invalid profile"}), 400
    license_context = get_user_license_context()
    if profile == "HUMAN" and license_context.get("human_profile_blocked"):
        return jsonify({
            "status": "error",
            "error": "Human profile is not included with Paid Monthly users.",
            "license_context": license_context,
        }), 403
    if profile == "CLOUD" and not bool(license_context.get("is_full_access") or license_context.get("is_lifetime")):
        return jsonify({
            "status": "error",
            "error": "Cloud Trading is available for lifetime users only.",
            "license_context": license_context,
        }), 403

    state["active_profile"] = profile
    cloud_status = None
    if profile == "CLOUD":
        cloud_key = _cloud_key_for_state(state)
        cloud_status = cloud_manager.status(cloud_key) if cloud_key else {"current_market": "", "running": False, "cloud_status": "Connect the exact Deriv API token to verify this Cloud session.", "requires_token_verification": True}
        if cloud_key:
            _ensure_tick_subscription(state, cloud_status.get("current_market") or state.get("current_symbol"), reason="cloud_profile", client_id=cid)
    elif profile == "HUMAN":
        _ensure_tick_subscription(state, state.get("human_symbol") or state.get("current_symbol"))
    else:
        _ensure_tick_subscription(state, state.get("current_symbol"))
    socketio.emit("profile_update", {"profile": profile, "symbol": (cloud_status.get("current_market") if profile == "CLOUD" and cloud_status else (state.get("human_symbol") if profile == "HUMAN" else state.get("current_symbol")))}, room=cid)
    def _finish_profile_switch_snapshot():
        try:
            if profile == "HUMAN":
                request_human_seed(cid)
            emit_profile_snapshot(cid)
        except Exception:
            logger.exception("[%s] profile switch snapshot failed for %s", cid, profile)

    try:
        socketio.start_background_task(_finish_profile_switch_snapshot)
    except Exception:
        _finish_profile_switch_snapshot()

    return jsonify({
        "status": "success",
        "profile": profile,
        "mutant_locked": bool(profile == "NTT" and not mutant_access.get("enabled")),
        "mutant_access": mutant_access,
        "license_context": license_context,
        "main_symbol": state.get("current_symbol"),
        "human_symbol": state.get("human_symbol") or state.get("current_symbol"),
        "symbol": (cloud_status.get("current_market") if profile == "CLOUD" and cloud_status else (state.get("human_symbol") if profile == "HUMAN" else state.get("current_symbol"))),
        "cloud_status": cloud_status,
        **_build_balance_payload(state, profile),
    })


