@app.route("/human_dual_market_contracts", methods=["POST"])
def human_dual_market_contracts_route():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    cid, state = get_client_state()
    data = request.json or {}
    logger.info(
        "[%s] TEMP backend_received_trade_request source=human_dual_market_contracts token_type=%s payload=%s",
        cid,
        _deriv_connection_type(state),
        _safe_deriv_payload_text(data),
    )
    legs = data.get("legs")
    if not isinstance(legs, list) or len(legs) != 2:
        return jsonify({"status": "error", "message": "Exactly two dual-market legs are required.", "placed": []}), 400

    ready, ready_msg = _ensure_trade_socket_ready(cid, state)
    if not ready:
        return jsonify({"status": "error", "message": ready_msg, "placed": []}), 400

    batch_id = str(data.get("batch_id") or _new_req_id())
    placed = []
    errors = []
    allowed_actions = {
        "RISE", "FALL", "EVEN", "ODD",
        "HIGH_TICK", "LOW_TICK", "ONLY_UPS", "ONLY_DOWNS",
    }
    for index, raw_leg in enumerate(legs, start=1):
        leg = raw_leg if isinstance(raw_leg, dict) else {}
        action = str(leg.get("action") or "").upper().strip()
        if action not in allowed_actions:
            errors.append(f"Leg {index}: invalid trade type")
            continue
        symbol = str(leg.get("symbol") or state.get("human_symbol") or state.get("current_symbol") or "R_10").strip()
        try:
            stake = max(0.35, float(leg.get("stake") or 0))
        except Exception:
            errors.append(f"Leg {index}: invalid stake")
            continue
        duration_unit = str(leg.get("duration_unit") or "t").strip().lower()
        if duration_unit not in ("t", "s", "m", "h"):
            duration_unit = "t"
        min_duration = 2 if action in ("ONLY_UPS", "ONLY_DOWNS") else 1
        try:
            duration = int(float(leg.get("duration_ticks") or leg.get("duration") or min_duration))
        except Exception:
            duration = min_duration
        duration = max(min_duration, min(1000, duration))
        extra_meta = {
            "dual_market_batch_id": batch_id,
            "dual_market_leg_index": index,
            "mode": "human_dual_market_contracts",
        }
        if action in ("RISE", "FALL"):
            ok, msg = place_risefall_order(cid, {
                "direction": action,
                "stake": stake,
                "duration": duration,
                "duration_unit": duration_unit,
                "symbol": symbol,
                "mode": "human_dual_market_contracts",
                "extra_meta": extra_meta,
            })
            trade = {
                "action": action,
                "label": action,
                "symbol": symbol,
                "duration": duration,
                "duration_unit": duration_unit,
            }
        elif action in ("EVEN", "ODD"):
            ok, msg = _send_human_parity_trade(
                cid,
                side=action,
                stake=stake,
                symbol=symbol,
                duration=duration,
                duration_unit=duration_unit,
                mode="human_dual_market_contracts",
                extra_meta=extra_meta,
            )
            trade = {
                "action": action,
                "label": action,
                "symbol": symbol,
                "duration": duration,
                "duration_unit": duration_unit,
            }
        else:
            ok, msg, trade = place_human_manual_contract(
                cid,
                action=action,
                stake=stake,
                selected_tick=leg.get("selected_tick"),
                duration_ticks=duration,
                symbol=symbol,
                mode="human_dual_market_contracts",
                extra_meta=extra_meta,
            )
        if ok:
            placed.append(trade or {"action": action, "symbol": symbol})
        else:
            errors.append(f"Leg {index}: {msg}")

    status = "success" if len(placed) == 2 else ("partial" if placed else "error")
    message = "Dual Market Contracts sent both trades" if status == "success" else "; ".join(errors or ["Dual Market Contracts failed"])
    return jsonify({
        "status": status,
        "message": message,
        "placed": placed,
        "errors": errors,
        "batch_id": batch_id,
    }), (200 if placed else 400)


@app.route("/human_parity_trade", methods=["POST"])
def human_parity_trade_route():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    cid, state = get_client_state()
    data = request.json or {}
    side = str(data.get("side") or "").upper().strip()
    if side not in ("EVEN", "ODD", "EVEN_ODD"):
        return jsonify({"error": "Invalid side. Use EVEN, ODD, or EVEN_ODD."}), 400

    symbol = data.get("symbol") or state.get("human_symbol") or state.get("current_symbol") or "R_10"
    duration = data.get("duration", data.get("parity_duration", 5))
    duration_unit = data.get("duration_unit", data.get("parity_duration_unit", "t"))
    mode = str(data.get("mode") or "").strip() or None
    plan = []
    if side in ("EVEN", "EVEN_ODD"):
        plan.append(("EVEN", data.get("even_stake", data.get("stake", 1.0))))
    if side in ("ODD", "EVEN_ODD"):
        plan.append(("ODD", data.get("odd_stake", data.get("stake", 1.0))))

    extra_base = _trade_extra_meta_from_payload(data) or {}
    if side == "EVEN_ODD":
        batch_id = str(data.get("batch_id") or _new_req_id())
        extra_base.update({
            "batch_id": batch_id,
            "batch_label": data.get("batch_label") or "Even+Odd",
            "batch_stake": data.get(
                "batch_stake",
                sum(_safe_money(stake) for _trade_side, stake in plan),
            ),
        })
        ready, ready_msg = _ensure_trade_socket_ready(cid, state)
        if not ready:
            return jsonify({"status": "error", "message": ready_msg, "placed": [], "batch_id": batch_id}), 400
        ws = state.get("ws")
        prepared = []
        for trade_side, stake in plan:
            leg_extra = dict(extra_base)
            leg_extra["leg_action"] = trade_side
            ok, item, msg = _prepare_human_parity_trade_request(
                state,
                side=trade_side,
                stake=stake,
                symbol=symbol,
                duration=duration,
                duration_unit=duration_unit,
                mode=mode,
                extra_meta=leg_extra,
            )
            if not ok:
                for prepared_item in prepared:
                    try:
                        state.get("req_meta", {}).pop(prepared_item.get("req_id"), None)
                        _release_profile_budget_reservation(state, prepared_item.get("budget_reservation"))
                    except Exception:
                        pass
                _emit_balance_payload(cid, state)
                return jsonify({"status": "error", "message": msg, "placed": [], "batch_id": batch_id}), 400
            prepared.append(item)
        placed = []
        lock = _get_ws_lifecycle_lock(state)
        with lock:
            for item in prepared:
                try:
                    ws.send(json.dumps(item["payload"]))
                    placed.append(item["side"])
                except Exception as exc:
                    for unsent in prepared[len(placed):]:
                        try:
                            state.get("req_meta", {}).pop(unsent.get("req_id"), None)
                            _release_profile_budget_reservation(state, unsent.get("budget_reservation"))
                        except Exception:
                            pass
                    _emit_balance_payload(cid, state)
                    return jsonify({
                        "status": "error",
                        "message": str(exc),
                        "placed": placed,
                        "batch_id": batch_id,
                    }), 400
        _emit_balance_payload(cid, state)
        return jsonify({
            "status": "success",
            "message": f"Sent {' + '.join(placed)}",
            "placed": placed,
            "batch_id": batch_id,
        })

    placed = []
    for trade_side, stake in plan:
        ok, msg = _send_human_parity_trade(
            cid,
            side=trade_side,
            stake=stake,
            symbol=symbol,
            duration=duration,
            duration_unit=duration_unit,
            mode=mode,
            extra_meta=extra_base or None,
        )
        if not ok:
            return jsonify({"status": "error", "message": msg, "placed": placed}), 400
        placed.append(trade_side)

    return jsonify({"status": "success", "message": f"Sent {' + '.join(placed)}", "placed": placed})


@app.route("/human_rf_trade", methods=["POST"])
def human_rf_trade():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    cid, state = get_client_state()
    strat = state.get("strategies", {}).get("HUMAN")
    if not strat or not hasattr(strat, "build_human_rf_trade_signal"):
        return jsonify({"error": "Human strategy not loaded"}), 400

    data = request.json or {}
    direction = (data.get("direction") or "AUTO").upper().strip()
    ignore_cooldown = bool(data.get("ignore_cooldown") or data.get("bypass_cooldown"))
    allow_equals = bool(data.get("allow_equals", False))
    duration_unit = _normalize_trade_duration_unit(data.get("duration_unit") or "t")
    requested_duration = _sanitize_trade_duration_for_unit(
        data.get("duration_ticks") or data.get("duration") or getattr(strat, "rf_duration_ticks", 5) or 5,
        duration_unit,
        default=getattr(strat, "rf_duration_ticks", 5) or 5,
    )

    # sync stake from request if provided (optional)
    try:
        if data.get("stake") is not None:
            strat.stake = float(data.get("stake"))
    except Exception:
        pass
    try:
        if data.get("duration_ticks") is not None and duration_unit == "t" and hasattr(strat, "set_human_rf_settings"):
            strat.set_human_rf_settings(duration_ticks=requested_duration)
    except Exception:
        pass

    if direction == "AUTO":
        sig = strat.build_human_rf_trade_signal(force_direction=None, require_threshold=True)
    elif direction in ("RISE", "FALL"):
        sig = strat.build_human_rf_trade_signal(
            force_direction=direction,
            require_threshold=False,
            ignore_cooldown=ignore_cooldown,
        )
    else:
        return jsonify({"error": "Invalid direction"}), 400

    if not sig:
        return jsonify({"error": "No valid setup / cooldown active"}), 400

    sig["symbol"] = state.get("human_symbol") or state.get("current_symbol")
    sig["duration"] = requested_duration
    sig["duration_unit"] = duration_unit
    if allow_equals:
        sig["allow_equals"] = True
    ok, msg = place_risefall_order(cid, sig)
    if ok:
        return jsonify({"status": "success", "signal": sig})
    return jsonify({"error": msg}), 500


@app.route("/human_auto_rise_fall", methods=["POST"])
@app.route("/human_formula_x", methods=["POST"])
def human_formula_x_route():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    cid, state = get_client_state()
    strat = state.get("strategies", {}).get("HUMAN")
    if not strat:
        return jsonify({"error": "Human strategy not loaded"}), 400

    data = request.json or {}
    rise_stake = max(0.35, float(data.get("rise_stake") or 0))
    fall_stake = max(0.35, float(data.get("fall_stake") or 0))
    duration_unit = _normalize_trade_duration_unit(data.get("duration_unit") or "t")
    duration_ticks = _sanitize_trade_duration_for_unit(
        data.get("duration_ticks") or getattr(strat, "rf_duration_ticks", 5) or 5,
        duration_unit,
        default=getattr(strat, "rf_duration_ticks", 5) or 5,
    )
    allow_equals = bool(data.get("allow_equals", False))

    symbol = state.get("human_symbol") or state.get("current_symbol")
    signals = [
        {
            "direction": "RISE",
            "stake": rise_stake,
            "duration": duration_ticks,
            "duration_unit": duration_unit,
            "symbol": symbol,
            "allow_equals": allow_equals,
            "mode": "human_auto_rise_fall" if request.path.endswith("human_auto_rise_fall") else "human_formula_x",
        },
        {
            "direction": "FALL",
            "stake": fall_stake,
            "duration": duration_ticks,
            "duration_unit": duration_unit,
            "symbol": symbol,
            "allow_equals": allow_equals,
            "mode": "human_auto_rise_fall" if request.path.endswith("human_auto_rise_fall") else "human_formula_x",
        },
    ]

    results = []
    lock = _get_ws_lifecycle_lock(state)
    with lock:
        for sig in signals:
            ok, msg = place_risefall_order(cid, sig)
            results.append((ok, msg))

    payload = strat.get_human_rf_payload()
    if state.get("active_profile") == "HUMAN":
        socketio.emit("human_rf_status", payload, room=cid)

    rise_ok, rise_msg = results[0]
    fall_ok, fall_msg = results[1]
    status = "success" if (rise_ok and fall_ok) else ("partial" if (rise_ok or fall_ok) else "error")
    pair_label = "AUTO RISE & FALL" if request.path.endswith("human_auto_rise_fall") else "FormulaX"
    message = f"{pair_label} sent both trades" if status == "success" else (rise_msg or fall_msg or f"{pair_label} failed")
    return jsonify({
        "status": status,
        "message": message,
        "payload": payload,
        "rise_ok": rise_ok,
        "fall_ok": fall_ok,
    }), (200 if status in ("success", "partial") else 500)


