# ---------------- HEARTBEAT SWEEPER ---------------- #
def heartbeat_sweeper():
    while True:
        time.sleep(max(5.0, float(HEARTBEAT_SWEEPER_INTERVAL_SEC)))
        now_ts = time.time()
        stale = []
        for client_id, state in list(clients.items()):
            if isinstance(state, dict) and state.get("cloud_runtime"):
                try:
                    if cloud_manager.status(state.get("username")).get("running"):
                        continue
                except Exception:
                    pass
            try:
                last_seen = float((state or {}).get("last_seen", 0.0) or 0.0)
            except Exception:
                last_seen = 0.0
            if not last_seen:
                continue
            age = now_ts - last_seen
            if age >= float(HEARTBEAT_TIMEOUT_SEC):
                stale.append((client_id, state, age))

        if stale:
            logger.info(
                "heartbeat_sweeper_stale_clients count=%s active_clients_before=%s timeout_sec=%s active_threads=%s",
                len(stale),
                len(clients),
                HEARTBEAT_TIMEOUT_SEC,
                threading.active_count(),
            )
        for client_id, state, age in stale:
            live_state = clients.get(client_id)
            if live_state is not state:
                continue
            try:
                _cleanup_client_runtime(client_id, state, reason=f"heartbeat_stale_{int(age)}s")
            except Exception:
                logger.exception("[%s] heartbeat_sweeper_cleanup_failed", client_id)
            try:
                clients.pop(client_id, None)
            except Exception:
                pass
        if stale:
            logger.info("heartbeat_sweeper_done active_clients_after=%s active_threads=%s", len(clients), threading.active_count())


@app.route("/toggle_named_ai_mode", methods=["POST"])
def toggle_named_ai_mode_route():
    if not login_required():
        return jsonify({"error": "Unauthorized"}), 403

    cid, state = get_client_state()
    data = request.json or {}
    profile = (data.get("profile") or state.get("active_profile") or "KOOLKID").upper().strip()
    mode_key = str(data.get("mode_key") or "").strip().lower()

    if profile not in ("KOOLKID", "JOKERJOE"):
        return jsonify({"status": "error", "message": "Invalid profile"}), 400
    if is_monthly_license_user():
        return monthly_feature_forbidden_response("Advanced AI modes")

    strat = state["strategies"].get(profile)
    if not strat or not hasattr(strat, "toggle_named_ai_mode"):
        return jsonify({"status": "error", "message": f"{profile} strategy not available"}), 400

    try:
        enabled = bool(strat.toggle_named_ai_mode(mode_key))
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 400

    try:
        payload = strat.get_ui_payload()
    except Exception:
        payload = {}
    auto_modes = {}
    try:
        auto_modes = (payload or {}).get("auto_modes", {}) or {}
    except Exception:
        auto_modes = {}

    try:
        socketio.emit("auto_mode_update", auto_modes, room=cid)
        socketio.emit("digit_analysis", payload, room=cid)
        if profile == "JOKERJOE":
            emit_jokerjoe_modes(cid, strat)
    except Exception:
        pass

    return jsonify({
        "status": "success",
        "profile": profile,
        "mode_key": mode_key,
        "enabled": enabled,
        "auto_modes": auto_modes,
        "payload": payload,
    })

threading.Thread(target=heartbeat_sweeper, daemon=True).start()


